	class SCOPED_ENVIRONMENT_VARIABLE final
	{
	public:
		explicit SCOPED_ENVIRONMENT_VARIABLE(const wchar_t* pName) :
			m_strName(pName)
		{
			SetLastError(ERROR_SUCCESS);
			const DWORD required = GetEnvironmentVariableW(
				m_strName.c_str(), nullptr, 0u);
			m_bWasDefined = 0u != required ||
				GetLastError() != ERROR_ENVVAR_NOT_FOUND;
			if (0u == required)
				return;
			std::vector<wchar_t> value(required);
			const DWORD length = GetEnvironmentVariableW(
				m_strName.c_str(), value.data(), required);
			if (0u != length && length < required)
				m_strOriginalValue.assign(value.data(), length);
		}

		~SCOPED_ENVIRONMENT_VARIABLE()
		{
			Restore();
		}

		SCOPED_ENVIRONMENT_VARIABLE(const SCOPED_ENVIRONMENT_VARIABLE&) = delete;
		SCOPED_ENVIRONMENT_VARIABLE& operator=(
			const SCOPED_ENVIRONMENT_VARIABLE&) = delete;

		bool_t Set(const wchar_t* pValue)
		{
			m_bRestored = false;
			return FALSE != SetEnvironmentVariableW(m_strName.c_str(), pValue);
		}

		bool_t Was_Defined() const { return m_bWasDefined; }
		const std::wstring& Get_OriginalValue() const { return m_strOriginalValue; }

		void Restore()
		{
			if (m_bRestored)
				return;
			SetEnvironmentVariableW(m_strName.c_str(),
				m_bWasDefined ? m_strOriginalValue.c_str() : nullptr);
			m_bRestored = true;
		}

	private:
		std::wstring m_strName;
		std::wstring m_strOriginalValue;
		bool_t m_bWasDefined = false;
		bool_t m_bRestored = false;
	};

	bool_t Collect_DimensionMasterEffectRoster(
		std::vector<uint32_t>& outSkillIds,
		std::vector<std::string>& outEffectIds,
		std::string& outStatus)
	{
		using namespace Client;
		using namespace LostArk::Shared;
		outSkillIds.clear();
		outEffectIds.clear();
		if (!CPlayerSkillCatalog::Load(outStatus))
			return false;

		for (const PLAYER_SKILL_DEFINITION& skill :
			CPlayerSkillCatalog::Get_Skills())
		{
			if (skill.eCharacterClass != CHARACTER_CLASS_ID::DIMENSIONMASTER ||
				skill.strInputSlot == "SPACE")
			{
				continue;
			}

			const std::string expectedEffectId =
				"effect.dimensionmaster.skill." +
				std::to_string(skill.iSkillId);
			if (skill.strEffectId != expectedEffectId)
			{
				outStatus = "DimensionMaster slot " + skill.strInputSlot +
					" must map skill " + std::to_string(skill.iSkillId) +
					" to " + expectedEffectId;
				return false;
			}

			outSkillIds.push_back(skill.iSkillId);
			outEffectIds.push_back(skill.strEffectId);
			for (std::size_t stage = 1u;
				stage <= skill.iComboStageCount; ++stage)
			{
				outEffectIds.push_back(skill.strEffectId + ".ba" +
					std::to_string(stage));
			}
		}

		if (outSkillIds.empty())
		{
			outStatus = "DimensionMaster trial effect roster is empty.";
			return false;
		}
		return true;
	}

	struct EFFECT_BUILD_ROW final
	{
		std::size_t iComponentCount = 0u;
		std::size_t iEmitterCount = 0u;
	};

	struct EFFECT_BUILD_CONTRACT final
	{
		std::size_t iEffectCount = 0u;
		std::size_t iComponentCount = 0u;
		std::size_t iEmitterCount = 0u;
		std::map<std::string, EFFECT_BUILD_ROW, std::less<>> Effects;
	};

	bool_t Read_ContractSize(
		const Client::DATA_JSON_VALUE& object,
		const char_t* pName,
		std::size_t& outValue)
	{
		const Client::DATA_JSON_VALUE* value = object.Find(pName);
		if (nullptr == value || !value->Is_Number() ||
			!std::isfinite(value->Get_Number()) ||
			value->Get_Number() != std::floor(value->Get_Number()) ||
			value->Get_Number() < 0.0 ||
			value->Get_Number() > static_cast<double>(
				(std::numeric_limits<std::size_t>::max)()))
		{
			return false;
		}
		outValue = static_cast<std::size_t>(value->Get_Number());
		return true;
	}

	bool_t Load_EffectBuildReceipt(
		const wchar_t* pRelativePath,
		const char_t* pExpectedCharacterClass,
		EFFECT_BUILD_CONTRACT& outContract,
		std::string& outStatus)
	{
		using namespace Client;
		outContract = {};
		const std::filesystem::path path = CProjectDataRoot::Resolve(pRelativePath);
		std::ifstream input(path, std::ios::binary);
		if (path.empty() || !input)
		{
			outStatus = std::string(pExpectedCharacterClass) +
				" component build receipt is missing.";
			return false;
		}
		std::string text{
			std::istreambuf_iterator<char_t>(input),
			std::istreambuf_iterator<char_t>() };
		if (text.starts_with("\xEF\xBB\xBF"))
			text.erase(0u, 3u);
		DATA_JSON_VALUE root;
		if (!CDataJson::Parse(text, root, outStatus) || !root.Is_Object())
			return false;

		const DATA_JSON_VALUE* schema = root.Find("schema");
		const DATA_JSON_VALUE* version = root.Find("version");
		const DATA_JSON_VALUE* characterClass = root.Find("characterClass");
		const DATA_JSON_VALUE* compileIdentity = root.Find("compileIdentityComplete");
		const DATA_JSON_VALUE* effects = root.Find("effects");
		if (nullptr == schema || !schema->Is_String() ||
			schema->Get_String() != "lostark.effect-component-build-receipt" ||
			nullptr == version || !version->Is_Number() ||
			version->Get_Number() != 1.0 ||
			nullptr == characterClass || !characterClass->Is_String() ||
			characterClass->Get_String() != pExpectedCharacterClass ||
			nullptr == compileIdentity || !compileIdentity->Is_Boolean() ||
			!compileIdentity->Get_Boolean() ||
			nullptr == effects || !effects->Is_Array() ||
			!Read_ContractSize(root, "effectCount", outContract.iEffectCount) ||
			!Read_ContractSize(root, "componentCount", outContract.iComponentCount) ||
			!Read_ContractSize(root, "emitterCount", outContract.iEmitterCount))
		{
			outStatus = std::string(pExpectedCharacterClass) +
				" component build receipt contract is invalid.";
			return false;
		}

		std::size_t componentTotal = 0u;
		std::size_t emitterTotal = 0u;
		for (const DATA_JSON_VALUE& effect : effects->Get_Array())
		{
			const DATA_JSON_VALUE* effectAssetId = effect.Find("effectAssetId");
			const DATA_JSON_VALUE* effectIdentity = effect.Find("compileIdentity");
			const DATA_JSON_VALUE* sourceSha = effect.Find("sourceDocumentSha256");
			const DATA_JSON_VALUE* compiledSha = effect.Find("compiledDocumentSha256");
			EFFECT_BUILD_ROW row;
			if (!effect.Is_Object() || nullptr == effectAssetId ||
				!effectAssetId->Is_String() || effectAssetId->Get_String().empty() ||
				nullptr == effectIdentity || !effectIdentity->Is_Boolean() ||
				!effectIdentity->Get_Boolean() || nullptr == sourceSha ||
				!sourceSha->Is_String() || nullptr == compiledSha ||
				!compiledSha->Is_String() ||
				sourceSha->Get_String() != compiledSha->Get_String() ||
				!Read_ContractSize(effect, "componentCount", row.iComponentCount) ||
				!Read_ContractSize(effect, "emitterCount", row.iEmitterCount) ||
				0u == row.iComponentCount || 0u == row.iEmitterCount ||
				!outContract.Effects.emplace(
					effectAssetId->Get_String(), row).second)
			{
				outStatus = std::string(pExpectedCharacterClass) +
					" component build receipt effect row is invalid.";
				return false;
			}
			componentTotal += row.iComponentCount;
			emitterTotal += row.iEmitterCount;
		}

		if (outContract.Effects.size() != outContract.iEffectCount ||
			componentTotal != outContract.iComponentCount ||
			emitterTotal != outContract.iEmitterCount)
		{
			outStatus = std::string(pExpectedCharacterClass) +
				" component build receipt totals disagree with its rows.";
			return false;
		}
		return true;
	}

	bool_t Load_FourClassEffectBuildContract(
		EFFECT_BUILD_CONTRACT& outContract,
		std::string& outStatus)
	{
		struct RECEIPT_SOURCE final
		{
			const wchar_t* pRelativePath = nullptr;
			const char_t* pCharacterClass = nullptr;
		};
		const RECEIPT_SOURCE Sources[] =
		{
			{ L"Effects/AuthoredCorrections/Generated/ComponentBuild/"
				L"Artist.component-build.receipt.json", "ARTIST" },
			{ L"Effects/AuthoredCorrections/Generated/ComponentBuild/"
				L"DimensionMaster.component-build.receipt.json", "DIMENSIONMASTER" },
			{ L"Effects/AuthoredCorrections/Generated/ComponentBuild/"
				L"LanceMaster.component-build.receipt.json", "LANCE_MASTER" },
			{ L"Effects/AuthoredCorrections/Generated/ComponentBuild/"
				L"Warlord.component-build.receipt.json", "WARLORD" }
		};

		outContract = {};
		for (const RECEIPT_SOURCE& source : Sources)
		{
			EFFECT_BUILD_CONTRACT receipt;
			if (!Load_EffectBuildReceipt(source.pRelativePath,
				source.pCharacterClass, receipt, outStatus))
			{
				outContract = {};
				return false;
			}
			outContract.iEffectCount += receipt.iEffectCount;
			outContract.iComponentCount += receipt.iComponentCount;
			outContract.iEmitterCount += receipt.iEmitterCount;
			for (const auto& entry : receipt.Effects)
			{
				if (!outContract.Effects.emplace(entry).second)
				{
					outStatus = "Four-class component build receipts contain a duplicate Effect ID.";
					outContract = {};
					return false;
				}
			}
		}

		if (101u != outContract.iEffectCount ||
			555u != outContract.iComponentCount ||
			2160u != outContract.iEmitterCount ||
			outContract.Effects.size() != outContract.iEffectCount)
		{
			outStatus = "Four-class component build receipt totals must be exactly 101/555/2160.";
			outContract = {};
			return false;
		}
		return true;
	}

	struct TEST_RUNNER final
	{
		void Require(const bool_t condition, const char_t* pName)
		{
			++iAssertionCount;
			if (condition)
			{
				std::cout << "[PASS] " << pName << '\n';
				return;
			}

			++iFailureCount;
			std::cout << "[FAILURE] " << pName << '\n';
		}

		std::size_t iAssertionCount = 0;
		std::size_t iFailureCount = 0;
	};

	void Test_PlayableCharacterPreviewComposition(TEST_RUNNER& Runner)
	{
		using namespace Client;
		using LostArk::Shared::CHARACTER_CLASS_ID;
		struct EXPECTED_PREVIEW final
		{
			CHARACTER_CLASS_ID eClass = CHARACTER_CLASS_ID::END;
			std::string strAssetName;
			std::string strBodyModel;
			std::vector<std::string> EquipmentModels;
			std::vector<std::string> WeaponModels;
			std::vector<std::wstring> PartTags;
			std::vector<std::string> WeaponSockets;
			std::vector<f32_t> WeaponYawDegrees;
		};

		const std::vector<EXPECTED_PREVIEW> Expected =
		{
			{
				CHARACTER_CLASS_ID::LANCE_MASTER,
				"LanceMaster",
				"Character/LanceMaster/LanceMaster.wmodel",
				{
					"Character/LanceMaster/LanceMaster_Upper.wmodel",
					"Character/LanceMaster/LanceMaster_Lower.wmodel",
					"Character/LanceMaster/LanceMaster_Arm.wmodel",
					"Character/LanceMaster/LanceMaster_Shoulder.wmodel",
					"Character/LanceMaster/LanceMaster_Helmet.wmodel",
					"Character/LanceMaster/LanceMaster_Helmet_Mokoko.wmodel",
					"Character/LanceMaster/LanceMaster_Upper_Mokoko.wmodel"
				},
				{
					"Character/WP_WFLM_00L/WP_WFLM_00L.wmodel",
					"Character/WP_WFLM_00S/WP_WFLM_00S.wmodel"
				},
				{
					L"Part_10_Equip_Arm", L"Part_10_Equip_Helmet",
					L"Part_10_Equip_Lower", L"Part_10_Equip_Shoulder",
					L"Part_10_Equip_Upper", L"Part_15_Avatar_Head",
					L"Part_15_Avatar_Armor", L"Part_90_Weapon_R",
					L"Part_91_Weapon_R_Short"
				},
				{ "b_weapon_rhand", "b_weapon_rhand" },
				{ 0.f, 0.f }
			},
			{
				CHARACTER_CLASS_ID::ARTIST,
				"Artist",
				"Character/Artist/Artist.wmodel",
				{
					"Character/Artist/Artist_Upper.wmodel",
					"Character/Artist/Artist_Lower.wmodel",
					"Character/Artist/Artist_Arm.wmodel",
					"Character/Artist/Artist_Shoulder.wmodel",
					"Character/Artist/Artist_Helmet.wmodel"
				},
				{ "Character/WP_WSDM_09/WP_WSDM_09.wmodel" },
				{
					L"Part_10_Equip_Arm", L"Part_10_Equip_Helmet",
					L"Part_10_Equip_Lower", L"Part_10_Equip_Shoulder",
					L"Part_10_Equip_Upper", L"Part_90_Weapon_R"
				},
				{ "b_wp_1" },
				{ 0.f }
			},
			{
				CHARACTER_CLASS_ID::DIMENSIONMASTER,
				"DimensionMaster",
				"Character/DimensionMaster/DimensionMaster_Character.wmodel",
				{},
				{
					"Character/WP_WSWP_M_06/WP_WSWP_M_06L.wmodel",
					"Character/WP_WSWP_M_06/WP_WSWP_M_06S.wmodel",
					"Character/WP_WSWP_M_06/WP_WSWP_M_06P.wmodel",
					"Character/WP_WSWP_M_06/WP_WSWP_M_06E.wmodel"
				},
				{
					L"Part_90_Weapon_L", L"Part_91_Weapon_S",
					L"Part_92_Weapon_P", L"Part_93_Weapon_E"
				},
				{
					"b_wp_swm_m_1", "b_wp_swm_m_2", "b_wp_swm_m_3",
					"b_wp_swm_m_4_02"
				},
				{ 0.f, 0.f, 0.f, 180.f }
			},
			{
				CHARACTER_CLASS_ID::WARLORD,
				"Warlord",
				"Character/Warlord/Warlord.wmodel",
				{
					"Character/Warlord/Warlord_Upper.wmodel",
					"Character/Warlord/Warlord_Lower.wmodel",
					"Character/Warlord/Warlord_Arm.wmodel",
					"Character/Warlord/Warlord_Shoulder.wmodel",
					"Character/Warlord/Warlord_Helmet.wmodel",
					"Character/Warlord/Warlord_Hair.wmodel"
				},
				{
					"Character/WP_WWGL_04/WP_WWGL_04.wmodel",
					"Character/WP_WWGL_SD_04/WP_WWGL_SD_04.wmodel"
				},
				{
					L"Part_10_Equip_Arm", L"Part_10_Equip_Hair",
					L"Part_10_Equip_Helmet", L"Part_10_Equip_Lower",
					L"Part_10_Equip_Shoulder", L"Part_10_Equip_Upper",
					L"Part_90_Weapon_R", L"Part_90_Weapon_L"
				},
				{ "b_weapon_rhand", "b_weapon_lhand" },
				{ 0.f, 0.f }
			}
		};

		bool_t bExactSelectorJoin = true;
		bool_t bExactResourceInventory = true;
		bool_t bExactPartAndSocketInventory = true;
		bool_t bBodyPaletteProviderParity = true;
		bool_t bStanceWeaponVisibilityParity = true;
		PLAYABLE_CHARACTER_PREVIEW_COMPOSITION LastComposition;
		const ANIMATION_PREVIEW_ASSET* pLastAsset = nullptr;
		const CHARACTER_SPEC* pLastSpec = nullptr;
		const CHARACTER_ACTOR_ENTRY* pLastActor = nullptr;

		for (const EXPECTED_PREVIEW& Row : Expected)
		{
			const auto Asset = std::find_if(
				ANIMATION_PREVIEW_ASSETS.begin(),
				ANIMATION_PREVIEW_ASSETS.end(),
				[&Row](const ANIMATION_PREVIEW_ASSET& Candidate)
				{
					return nullptr != Candidate.pAssetName &&
						Row.strAssetName == Candidate.pAssetName;
				});
			const CHARACTER_SPEC* Spec = CCharacterCatalog::Find_Spec(Row.eClass);
			const CHARACTER_ACTOR_ENTRY* Actor =
				CActorCatalog::Find_Character(Row.eClass);
			PLAYABLE_CHARACTER_PREVIEW_COMPOSITION Composition;
			const bool_t bJoined =
				Asset != ANIMATION_PREVIEW_ASSETS.end() && nullptr != Spec &&
				nullptr != Actor &&
				CPlayableCharacterPreviewContract::Stage(*Asset, Composition);
			bExactSelectorJoin = bExactSelectorJoin && bJoined &&
				Composition.pSpec == Spec && Composition.pActor == Actor;
			if (!bJoined)
				continue;

			bExactResourceInventory = bExactResourceInventory &&
				Actor->bodyModel == Row.strBodyModel &&
				Actor->equipmentModels == Row.EquipmentModels &&
				Actor->weaponModels == Row.WeaponModels;

			std::vector<std::wstring> PartTags;
			std::vector<std::string> WeaponSockets;
			std::vector<f32_t> WeaponYawDegrees;
			for (uint32_t Index = 0u; Index < Spec->iNumEquipment; ++Index)
				PartTags.emplace_back(Spec->pEquipment[Index].pPartTag);
			for (uint32_t Index = 0u; Index < Spec->iNumWeapons; ++Index)
			{
				PartTags.emplace_back(Spec->pWeapons[Index].pPartTag);
				WeaponSockets.emplace_back(Spec->pWeapons[Index].pSocketBone);
				WeaponYawDegrees.push_back(
					Spec->pWeapons[Index].fSocketYawDegrees);
			}
			bExactPartAndSocketInventory = bExactPartAndSocketInventory &&
				PartTags == Row.PartTags &&
				WeaponSockets == Row.WeaponSockets &&
				WeaponYawDegrees == Row.WeaponYawDegrees;
			bBodyPaletteProviderParity = bBodyPaletteProviderParity &&
				Composition.eOwnerKind ==
					PLAYABLE_PREVIEW_OWNER_KIND::CHARACTER &&
				Composition.iBodyPalettePartCount == Spec->iNumEquipment &&
				Composition.iBodySocketPartCount == Spec->iNumWeapons;
			const uint32_t ExpectedVisibleWeapons =
				CHARACTER_CLASS_ID::LANCE_MASTER == Row.eClass ? 1u :
					Spec->iNumWeapons;
			bStanceWeaponVisibilityParity =
				bStanceWeaponVisibilityParity &&
				Composition.iFallbackVisibleWeaponPartCount ==
					ExpectedVisibleWeapons &&
				(CHARACTER_CLASS_ID::LANCE_MASTER != Row.eClass ||
					Composition.eFallbackStance ==
						LostArk::Shared::PLAYER_STANCE_ID::
							LANCE_MASTER_LONG_SPEAR);

			LastComposition = Composition;
			pLastAsset = &*Asset;
			pLastSpec = Spec;
			pLastActor = Actor;
		}

		Runner.Require(bExactSelectorJoin,
			"Model View Four-Class Selector Joins Exact Character Specs");
		Runner.Require(bExactResourceInventory,
			"Model View Four-Class Body Equipment Weapon Asset Inventory");
		Runner.Require(bExactPartAndSocketInventory,
			"Model View Four-Class Part Tags Socket Bones And Yaw");
		Runner.Require(bBodyPaletteProviderParity,
			"Model View Uses Full Character Body Palette And Socket Provider");
		Runner.Require(bStanceWeaponVisibilityParity,
			"Model View Lance Fallback Shows One Long Spear And Keeps Other Class Weapon Inventories");

		bool_t bMissingPartRollback = false;
		if (nullptr != pLastAsset && nullptr != pLastSpec &&
			nullptr != pLastActor && !pLastActor->equipmentModels.empty())
		{
			CHARACTER_ACTOR_ENTRY MissingPartActor = *pLastActor;
			MissingPartActor.equipmentModels.pop_back();
			const PLAYABLE_CHARACTER_PREVIEW_COMPOSITION Before =
				LastComposition;
			bMissingPartRollback =
				!CPlayableCharacterPreviewContract::Stage(
					*pLastAsset, *pLastSpec, MissingPartActor,
					LastComposition) &&
				LastComposition.pSpec == Before.pSpec &&
				LastComposition.pActor == Before.pActor &&
				LastComposition.eOwnerKind == Before.eOwnerKind &&
				LastComposition.iBodyPalettePartCount ==
					Before.iBodyPalettePartCount &&
				LastComposition.iBodySocketPartCount ==
					Before.iBodySocketPartCount &&
				LastComposition.eFallbackStance == Before.eFallbackStance &&
				LastComposition.iFallbackVisibleWeaponPartCount ==
					Before.iFallbackVisibleWeaponPartCount;
		}
		Runner.Require(bMissingPartRollback,
			"Model View Missing Part Rejects Without Replacing Prior Composition");
	}

	bool_t Is_AnisotropicSamplerFilter(const D3D11_FILTER Filter)
	{
		return Filter == D3D11_FILTER_ANISOTROPIC ||
			Filter == D3D11_FILTER_COMPARISON_ANISOTROPIC ||
			Filter == D3D11_FILTER_MINIMUM_ANISOTROPIC ||
			Filter == D3D11_FILTER_MAXIMUM_ANISOTROPIC;
	}

	bool_t Same_SamplerDescriptor(
		const D3D11_SAMPLER_DESC& Left,
		const D3D11_SAMPLER_DESC& Right)
	{
		return Left.Filter == Right.Filter &&
			Left.AddressU == Right.AddressU &&
			Left.AddressV == Right.AddressV &&
			Left.AddressW == Right.AddressW &&
			Left.MipLODBias == Right.MipLODBias &&
			Left.MaxAnisotropy == Right.MaxAnisotropy &&
			Left.ComparisonFunc == Right.ComparisonFunc &&
			std::equal(std::begin(Left.BorderColor), std::end(Left.BorderColor),
				std::begin(Right.BorderColor)) &&
			Left.MinLOD == Right.MinLOD && Left.MaxLOD == Right.MaxLOD;
	}

	bool_t Materialize_RuntimeSamplerDescriptor(
		const D3D11_SAMPLER_DESC& Authority,
		D3D11_SAMPLER_DESC& OutRuntime)
	{
		OutRuntime = Authority;
		const bool_t bAnisotropic =
			Is_AnisotropicSamplerFilter(Authority.Filter);
		if (0u == OutRuntime.MaxAnisotropy)
		{
			if (bAnisotropic)
				return false;
			OutRuntime.MaxAnisotropy = 1u;
		}
		return OutRuntime.MaxAnisotropy <= 16u;
	}

	bool_t Same_RuntimeSamplerReadbackDescriptor(
		const D3D11_SAMPLER_DESC& Actual,
		const D3D11_SAMPLER_DESC& Requested,
		const D3D11_SAMPLER_DESC& FrozenAuthority)
	{
		D3D11_SAMPLER_DESC CanonicalRequested = Requested;
		if (!Is_AnisotropicSamplerFilter(FrozenAuthority.Filter) &&
			0u == FrozenAuthority.MaxAnisotropy &&
			1u == Requested.MaxAnisotropy)
		{
			CanonicalRequested.MaxAnisotropy = 0u;
		}
		return Same_SamplerDescriptor(Actual, CanonicalRequested);
	}

	bool_t Stage_Artist31470GpuTextureBinding(
		ID3D11Device* pDevice,
		const std::filesystem::path& ResourcesRoot,
		const Client::EFFECT_RECONSTRUCTED_RENDER_TEXTURE_BINDING& Binding,
		std::string& strOutStatus)
	{
		strOutStatus.clear();
		if (nullptr == pDevice || Binding.strRuntimeAssetId.empty())
		{
			strOutStatus = "GPU texture-stage input is invalid.";
			return false;
		}
		const std::filesystem::path Relative =
			std::filesystem::path(Binding.strRuntimeAssetId).lexically_normal();
		if (Relative.is_absolute() || Relative.has_root_name() ||
			std::any_of(Relative.begin(), Relative.end(),
				[](const std::filesystem::path& Part)
				{
					return Part == L"..";
				}))
		{
			strOutStatus = "GPU texture-stage asset id escapes Resources.";
			return false;
		}
		const std::filesystem::path TexturePath = ResourcesRoot / Relative;
		std::ifstream Input(TexturePath, std::ios::binary);
		if (!Input)
		{
			strOutStatus = "GPU texture-stage asset is missing: " +
				Binding.strRuntimeAssetId;
			return false;
		}
		const std::vector<uint8_t> Bytes{
			std::istreambuf_iterator<char>(Input),
			std::istreambuf_iterator<char>() };
		const std::string_view ByteView(
			reinterpret_cast<const char*>(Bytes.data()), Bytes.size());
		if (Bytes.size() != Binding.iActualDdsByteCount ||
			Client::CEffectRuntimeAuthorityCodec::Compute_Sha256Hex(ByteView) !=
				Binding.strActualDdsRawSha256)
		{
			strOutStatus = "GPU texture-stage DDS bytes changed: " +
				Binding.strRuntimeAssetId;
			return false;
		}

		const DirectX::DDS_LOADER_FLAGS Flags =
			Binding.ActualDdsSrv.strColorSpace == "SRGB" ?
				DirectX::DDS_LOADER_FORCE_SRGB :
				DirectX::DDS_LOADER_IGNORE_SRGB;
		ComPtr<ID3D11ShaderResourceView> Texture;
		if (FAILED(DirectX::CreateDDSTextureFromMemoryEx(
			pDevice, Bytes.data(), Bytes.size(), 0u, D3D11_USAGE_DEFAULT,
			D3D11_BIND_SHADER_RESOURCE, 0u, 0u, Flags, nullptr, &Texture)) ||
			nullptr == Texture)
		{
			strOutStatus = "GPU texture-stage DDS upload failed: " +
				Binding.strRuntimeAssetId;
			return false;
		}
		D3D11_SHADER_RESOURCE_VIEW_DESC Srv{};
		Texture->GetDesc(&Srv);
		if (Srv.Format != Binding.ActualDdsSrv.eFormat ||
			Srv.ViewDimension != Binding.ActualDdsSrv.eViewDimension ||
			Srv.Texture2D.MostDetailedMip !=
				Binding.ActualDdsSrv.iMostDetailedMip ||
			Srv.Texture2D.MipLevels != Binding.ActualDdsSrv.iMipLevels)
		{
			strOutStatus = "GPU texture-stage SRV descriptor changed: " +
				Binding.strRuntimeAssetId;
			return false;
		}

		D3D11_SAMPLER_DESC RuntimeSampler{};
		if (!Materialize_RuntimeSamplerDescriptor(
			Binding.SamplerDescriptor, RuntimeSampler))
		{
			strOutStatus = "GPU texture-stage sampler authority is invalid.";
			return false;
		}
		ComPtr<ID3D11SamplerState> Sampler;
		if (FAILED(pDevice->CreateSamplerState(&RuntimeSampler, &Sampler)) ||
			nullptr == Sampler)
		{
			strOutStatus = "GPU texture-stage sampler creation failed.";
			return false;
		}
		D3D11_SAMPLER_DESC Readback{};
		Sampler->GetDesc(&Readback);
		if (!Same_RuntimeSamplerReadbackDescriptor(
			Readback, RuntimeSampler, Binding.SamplerDescriptor))
		{
			strOutStatus = "GPU texture-stage sampler readback changed.";
			return false;
		}
		return true;
	}

