	void Test_SkillBindingSchema(TEST_RUNNER& runner)
	{
		using namespace Client;
		using namespace LostArk::Shared;
		const auto skills = Make_SkillFixture();
		const std::vector<std::string> clips =
			{ "Active_A", "Active_B", "BA_1", "BA_2", "BA_3" };
		const std::string valid =
			"{\"schema\":\"lostark.animation-skill-bindings\","
			"\"formatVersion\":3,\"animationAssetId\":\"LanceMaster\","
			"\"characterClass\":\"LANCE_MASTER\",\"bindings\":["
			"{\"skillId\":101,\"clips\":[\"Active_A\","
			"{\"clip\":\"Active_B\",\"playMs\":250,\"playRate\":1.25}]},"
			"{\"skillId\":102,\"clips\":[[\"BA_1\"],[\"BA_2\"],[\"BA_3\"]]}]}";
		ANIMATION_SKILL_BINDING_DOCUMENT output;
		std::string status;
		runner.Require(
			CAnimationSkillBindingDocument::Parse_Text(valid, output, status) &&
			CAnimationSkillBindingDocument::Validate(output, "LanceMaster",
				CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Valid Parse And Catalog Join");

		runner.Require(
			1u == output.Bindings[0].Stages.size() &&
			2u == output.Bindings[0].Stages[0].Clips.size() &&
			3u == output.Bindings[1].Stages.size() &&
			1u == output.Bindings[1].Stages[0].Clips.size(),
			"Skill Binding Flat Clips Are One Stage And Nested Clips Are Many");

		const std::string wrongVersion =
			"{\"schema\":\"lostark.animation-skill-bindings\","
			"\"formatVersion\":2,\"animationAssetId\":\"LanceMaster\","
			"\"characterClass\":\"LANCE_MASTER\",\"bindings\":["
			"{\"skillId\":101,\"clips\":[\"Active_A\"]}]}";
		const std::string badPlayMs =
			"{\"schema\":\"lostark.animation-skill-bindings\","
			"\"formatVersion\":3,\"animationAssetId\":\"LanceMaster\","
			"\"characterClass\":\"LANCE_MASTER\",\"bindings\":["
			"{\"skillId\":101,\"clips\":["
			"{\"clip\":\"Active_A\",\"playMs\":0}]}]}";
		const std::string traversal =
			"{\"schema\":\"lostark.animation-skill-bindings\","
			"\"formatVersion\":3,\"animationAssetId\":\"../Escape\","
			"\"characterClass\":\"LANCE_MASTER\",\"bindings\":["
			"{\"skillId\":101,\"clips\":[\"Active_A\"]}]}";
		const std::string mixedShape =
			"{\"schema\":\"lostark.animation-skill-bindings\","
			"\"formatVersion\":3,\"animationAssetId\":\"LanceMaster\","
			"\"characterClass\":\"LANCE_MASTER\",\"bindings\":["
			"{\"skillId\":102,\"clips\":[[\"BA_1\"],\"BA_2\",[\"BA_3\"]]}]}";
		const std::string emptyStage =
			"{\"schema\":\"lostark.animation-skill-bindings\","
			"\"formatVersion\":3,\"animationAssetId\":\"LanceMaster\","
			"\"characterClass\":\"LANCE_MASTER\",\"bindings\":["
			"{\"skillId\":102,\"clips\":[[\"BA_1\"],[],[\"BA_3\"]]}]}";
		const std::string extraField = valid.substr(0u, valid.size() - 1u) +
			",\"unexpected\":true}";
		runner.Require(!CAnimationSkillBindingDocument::Parse_Text(
			wrongVersion, output, status), "Skill Binding Rejects Wrong Version");
		runner.Require(!CAnimationSkillBindingDocument::Parse_Text(
			traversal, output, status), "Skill Binding Rejects Traversal Asset");
		runner.Require(!CAnimationSkillBindingDocument::Parse_Text(
			extraField, output, status), "Skill Binding Rejects Extra Field");
		runner.Require(!CAnimationSkillBindingDocument::Parse_Text(
			badPlayMs, output, status), "Skill Binding Rejects Zero Clip Play Length");
		runner.Require(!CAnimationSkillBindingDocument::Parse_Text(
			mixedShape, output, status), "Skill Binding Rejects Mixed Stage Shape");
		runner.Require(!CAnimationSkillBindingDocument::Parse_Text(
			emptyStage, output, status), "Skill Binding Rejects Empty Stage");

		auto invalid = Make_BindingFixture();
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"Artist", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Wrong Owner");
		invalid = Make_BindingFixture();
		invalid.Bindings[1].iSkillId = 101u;
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"LanceMaster", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Duplicate Skill");
		invalid = Make_BindingFixture();
		invalid.Bindings.pop_back();
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"LanceMaster", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Missing Skill");
		invalid = Make_BindingFixture();
		invalid.Bindings[0].iSkillId = 999u;
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"LanceMaster", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Unknown Skill");
		invalid = Make_BindingFixture();
		invalid.Bindings[0].Stages[0].Clips[0].strClipName = "Missing_Clip";
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"LanceMaster", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Unknown Model Clip");
		invalid = Make_BindingFixture();
		invalid.Bindings[1].Stages.pop_back();
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"LanceMaster", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Combo Count Mismatch");
		/* An ACTIVE chain is one stage by contract: splitting it would silently
		make the client wait for a stage the Server never sends. */
		invalid = Make_BindingFixture();
		invalid.Bindings[0].Stages.push_back(
			{ { { "Active_B", 0u, 1.f } } });
		runner.Require(!CAnimationSkillBindingDocument::Validate(invalid,
			"LanceMaster", CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, status),
			"Skill Binding Rejects Staged Active Skill");

		ANIMATION_SKILL_BINDING_DOCUMENT preserved = Make_BindingFixture();
		runner.Require(!CAnimationSkillBindingDocument::Load_FromPath(
			L"Z:/definitely/missing/skillbindings.json", "LanceMaster",
			CHARACTER_CLASS_ID::LANCE_MASTER, skills, clips, preserved, status) &&
			2u == preserved.Bindings.size() &&
			"Active_A" == preserved.Bindings[0].Stages[0].Clips[0].strClipName,
			"Skill Binding Failed Staged Load Preserves Prior Output");
	}

	void Test_ValtanPatternBindingSchema(TEST_RUNNER& runner)
	{
		using namespace Client;
		SCOPED_ENVIRONMENT_VARIABLE runtimeResourceRoot(
			L"LOSTARK_RESOURCE_ROOT");
		if (!runtimeResourceRoot.Was_Defined() ||
			runtimeResourceRoot.Get_OriginalValue().empty())
		{
			const std::filesystem::path resourceRoot =
				(CProjectDataRoot::Get().parent_path() / L"Client" / L"Bin" /
				 L"Resources").lexically_normal();
			runtimeResourceRoot.Set(resourceRoot.c_str());
		}
		const std::vector<std::string> clips = {
			"mesh_att_battle_20_02",
			"mesh_att_battle_20_03",
			"mesh_att_battle_20_04" };
		const std::string valid =
			"{\"schema\":\"lostark.valtan-pattern-bindings\","
			"\"formatVersion\":1,\"bossArchetypeId\":\"BOSS_VALTAN\","
			"\"bindings\":["
			"{\"actionId\":\"valtan.attack.whirlwind.windup\","
			"\"clip\":\"mesh_att_battle_20_02\"},"
			"{\"actionId\":\"valtan.attack.whirlwind.active\","
			"\"clip\":[\"mesh_att_battle_20_03\",\"mesh_att_battle_20_04\","
			"\"mesh_att_battle_20_03\"]},"
			"{\"actionId\":\"valtan.attack.whirlwind.recovery\","
			"\"clip\":\"mesh_att_battle_20_04\"}]}";
		BOSS_PATTERN_ANIMATION_BINDING_DOCUMENT document;
		std::string status;
		runner.Require(
			CValtanPatternAnimationBindingDocument::Parse_Text(
				valid, document, status) &&
			CValtanPatternAnimationBindingDocument::Validate(
				document, "BOSS_VALTAN", clips, status) &&
			3u == document.Bindings.size() &&
			1u == document.Bindings[0].Clips.size() &&
			3u == document.Bindings[1].Clips.size() &&
			"mesh_att_battle_20_03" == document.Bindings[1].Clips[0] &&
			"mesh_att_battle_20_04" == document.Bindings[1].Clips[1] &&
			"mesh_att_battle_20_03" == document.Bindings[1].Clips[2],
			"Valtan Pattern Binding Parses Single Clips And Ordered Chains");

		auto invalid = document;
		invalid.Bindings[2].strActionId = invalid.Bindings[1].strActionId;
		runner.Require(
			!CValtanPatternAnimationBindingDocument::Validate(
				invalid, "BOSS_VALTAN", clips, status),
			"Valtan Pattern Binding Rejects Duplicate Action Identity");
		invalid = document;
		invalid.Bindings[1].Clips[1] = "missing_clip";
		runner.Require(
			!CValtanPatternAnimationBindingDocument::Validate(
				invalid, "BOSS_VALTAN", clips, status),
			"Valtan Pattern Binding Rejects Missing Model Clip In A Chain");
		const std::string emptyChain =
			"{\"schema\":\"lostark.valtan-pattern-bindings\","
			"\"formatVersion\":1,\"bossArchetypeId\":\"BOSS_VALTAN\","
			"\"bindings\":["
			"{\"actionId\":\"valtan.attack.whirlwind.active\","
			"\"clip\":[]}]}";
		BOSS_PATTERN_ANIMATION_BINDING_DOCUMENT emptyChainDocument;
		runner.Require(
			!CValtanPatternAnimationBindingDocument::Parse_Text(
				emptyChain, emptyChainDocument, status),
			"Valtan Pattern Binding Rejects An Empty Clip Chain");
		invalid = document;
		invalid.Bindings[1].Clips.clear();
		runner.Require(
			!CValtanPatternAnimationBindingDocument::Validate(
				invalid, "BOSS_VALTAN", clips, status),
			"Valtan Pattern Binding Validation Rejects Empty Clip Chain");
		runner.Require(
			!CValtanPatternAnimationBindingDocument::Validate(
				document, "BOSS_OTHER", clips, status),
			"Valtan Pattern Binding Rejects Wrong Boss Owner");

		const std::string validV2 =
			"{\"schema\":\"lostark.valtan-pattern-bindings\","
			"\"formatVersion\":2,\"bossArchetypeId\":\"BOSS_VALTAN\","
			"\"bindings\":[{\"actionId\":\"valtan.attack.whirlwind.active\","
			"\"clips\":["
			"{\"clipOccurrenceId\":\"test.whirlwind.active.clip.01\","
			"\"clip\":\"mesh_att_battle_20_03\","
			"\"mappingBasis\":\"CURRENT_PRODUCT_BASELINE\","
			"\"sourceStartMs\":100,\"playMs\":300,\"playRate\":2.0,"
			"\"loop\":false},"
			"{\"clipOccurrenceId\":\"test.whirlwind.active.clip.02\","
			"\"clip\":\"mesh_att_battle_20_04\","
			"\"mappingBasis\":\"ANIMATION_PR_127\","
			"\"sourceStartMs\":0,\"playMs\":0,\"playRate\":1.0,"
			"\"loop\":true}]}]}";
		BOSS_PATTERN_ANIMATION_BINDING_DOCUMENT v2Document;
		const bool_t v2BindingValid =
			CValtanPatternAnimationBindingDocument::Parse_Text(
				validV2, v2Document, status) &&
			CValtanPatternAnimationBindingDocument::Validate(
				v2Document, "BOSS_VALTAN", clips, status);
		runner.Require(v2BindingValid && 2u == v2Document.iFormatVersion &&
			2u == v2Document.Bindings.front().Clips.size() &&
			100u == v2Document.Bindings.front().Clips.front().iSourceStartMs &&
			300u == v2Document.Bindings.front().Clips.front().iPlayMs &&
			2.f == v2Document.Bindings.front().Clips.front().fPlayRate &&
			v2Document.Bindings.front().Clips.back().bLoop,
			"Valtan Pattern Binding V2 Preserves Ordered Occurrence Segment Rate And Final Loop");
		if (v2BindingValid)
		{
			auto invalidV2 = v2Document;
			invalidV2.Bindings.front().Clips.back().strClipOccurrenceId =
				invalidV2.Bindings.front().Clips.front().strClipOccurrenceId;
			runner.Require(
				!CValtanPatternAnimationBindingDocument::Validate(
					invalidV2, "BOSS_VALTAN", clips, status),
				"Valtan Pattern Binding V2 Rejects Duplicate Clip Occurrence Identity");
			invalidV2 = v2Document;
			invalidV2.Bindings.front().Clips.front().strMappingBasis =
				"UNREVIEWED_GUESS";
			runner.Require(
				!CValtanPatternAnimationBindingDocument::Validate(
					invalidV2, "BOSS_VALTAN", clips, status),
				"Valtan Pattern Binding V2 Rejects Unknown Mapping Basis");
			invalidV2 = v2Document;
			invalidV2.Bindings.front().Clips.front().bLoop = true;
			runner.Require(
				!CValtanPatternAnimationBindingDocument::Validate(
					invalidV2, "BOSS_VALTAN", clips, status),
				"Valtan Pattern Binding V2 Rejects A Non-Final Loop");
		}
		else
		{
			runner.Require(false,
				"Valtan Pattern Binding V2 Rejects Duplicate Clip Occurrence Identity");
			runner.Require(false,
				"Valtan Pattern Binding V2 Rejects Unknown Mapping Basis");
			runner.Require(false,
				"Valtan Pattern Binding V2 Rejects A Non-Final Loop");
		}

		const std::string extraField = valid.substr(0u, valid.size() - 1u) +
			",\"unexpected\":true}";
		BOSS_PATTERN_ANIMATION_BINDING_DOCUMENT preserved = document;
		runner.Require(
			!CValtanPatternAnimationBindingDocument::Parse_Text(
				extraField, preserved, status) &&
			preserved == document,
			"Valtan Pattern Binding Parse Failure Preserves Prior Output");

		BOSS_PATTERN_EFFECT_BINDING_DOCUMENT effectDocument;
		const bool_t bLoadedEffectDocument =
			CValtanPatternEffectBindingDocument::Load(
				"Valtan", "BOSS_VALTAN", clips, effectDocument, status);
		const bool_t bHasOneEffectBinding =
			bLoadedEffectDocument && 1u == effectDocument.Bindings.size();
		const BOSS_PATTERN_EFFECT_BINDING* effectBinding =
			bHasOneEffectBinding ? &effectDocument.Bindings.front() : nullptr;
		runner.Require(
			nullptr != effectBinding &&
			"VALTAN_WHIRLWIND" == effectBinding->strPatternId &&
			"valtan.attack.whirlwind.active" == effectBinding->strActionId &&
			"mesh_att_battle_20_03" == effectBinding->strRuntimeClipName &&
			"b_effectroot" == effectBinding->strRuntimeBoneName &&
			effectBinding->strProductAdmissionStatus == "ADMITTED_PRODUCT" &&
			effectBinding->bProductCatalogMapped &&
			effectBinding->bAnimationEventMapped,
			"Valtan Pattern Effect Parses Action Qualified Canary Mapping");

		EFFECT_DOCUMENT_DESC valtanWhirlwindDocument;
		CEffectPlayback valtanWhirlwindPlayback;
		const std::string dataPrefix = "Data/";
		const bool_t bValtanWhirlwindStagesOrdinaryDocument =
			nullptr != effectBinding &&
			effectBinding->strEffectDocument.rfind(dataPrefix, 0u) == 0u &&
			CEffectDocumentCodec::Load(
				CProjectDataRoot::Resolve(
					effectBinding->strEffectDocument.substr(dataPrefix.size())),
				valtanWhirlwindDocument, status) &&
			valtanWhirlwindDocument.strEffectAssetId ==
				effectBinding->strEffectAssetId &&
			CEffectDocumentCodec::Validate_Drawable(
				valtanWhirlwindDocument, status) &&
			valtanWhirlwindPlayback.Stage_Document(
				valtanWhirlwindDocument, status);
		if (!bValtanWhirlwindStagesOrdinaryDocument)
		{
			std::cout << "[DETAIL] Valtan Whirlwind authored v13 stage: " <<
				status << '\n';
		}
		runner.Require(bValtanWhirlwindStagesOrdinaryDocument,
			"Valtan Whirlwind Canary Loads And Stages Through Ordinary Authored V13 Playback");

		if (bHasOneEffectBinding)
		{
			BOSS_PATTERN_EFFECT_BINDING_DOCUMENT invalidEffects = effectDocument;
			invalidEffects.Bindings.front().strRuntimeClipName = "missing_clip";
			runner.Require(
				!CValtanPatternEffectBindingDocument::Validate(
					invalidEffects, "BOSS_VALTAN", clips, status),
				"Valtan Pattern Effect Rejects Missing Model Clip");
			invalidEffects = effectDocument;
			invalidEffects.Bindings.front().bAnimationEventMapped = false;
			runner.Require(
				!CValtanPatternEffectBindingDocument::Validate(
					invalidEffects, "BOSS_VALTAN", clips, status),
				"Valtan Pattern Effect Rejects Incomplete Product Admission");
		}
		else
		{
			runner.Require(false,
				"Valtan Pattern Effect Rejects Missing Model Clip");
			runner.Require(false,
				"Valtan Pattern Effect Rejects Incomplete Product Admission");
		}

		VALTAN_PATTERN_EFFECT_CUE_DOCUMENT patternCueDocument;
		const bool_t patternCuesLoaded =
			CValtanPatternEffectCueDocument::Load_Source(
				patternCueDocument, status);
		std::unordered_set<std::string> patternCueBindings;
		std::unordered_set<std::string> patternCueOccurrences;
		std::unordered_set<std::string> patternCueActions;
		std::unordered_set<std::string> patternCueEffects;
		bool_t patternCueIdentitiesExact = patternCuesLoaded &&
			patternCueDocument.strOwnerArchetypeId == "BOSS_VALTAN" &&
			patternCueDocument.iFormatVersion == 2u &&
			!patternCueDocument.Cues.empty();
		for (const VALTAN_PATTERN_EFFECT_CUE& cue : patternCueDocument.Cues)
		{
			const bool_t sourceWindowExact = cue.bHasSourceEnd ?
				(cue.eStopPolicy == EFFECT_STOP_POLICY::CUE_END &&
				 cue.iStartMs < cue.iEndMs) :
				(cue.eStopPolicy == EFFECT_STOP_POLICY::NATURAL &&
				 cue.iStartMs == cue.iEndMs);
			patternCueIdentitiesExact = patternCueIdentitiesExact &&
				patternCueBindings.insert(cue.strBindingId).second &&
				patternCueOccurrences.insert(cue.strOccurrenceId).second &&
				!cue.strClipOccurrenceId.empty() && sourceWindowExact &&
				0u != cue.iStageDurationMs;
			patternCueActions.insert(cue.strActionId);
			patternCueEffects.insert(cue.strEffectAssetId);
		}
		runner.Require(patternCueIdentitiesExact &&
			patternCueBindings.size() == patternCueDocument.Cues.size() &&
			patternCueOccurrences.size() == patternCueDocument.Cues.size() &&
			!patternCueActions.empty() && !patternCueEffects.empty() &&
			patternCueEffects.size() <= patternCueDocument.Cues.size(),
			"Valtan Product Pattern Effect Cue V2 Has Stable Occurrences, Policy-Exact Source Windows, And A Deduplicable Target Set");

		CEncounterPatternReference encounter;
		const bool_t encounterLoaded = encounter.Load(CProjectDataRoot::Resolve(
			std::filesystem::path(L"Encounters") / L"Valtan" /
			L"ValtanEncounter.json"), status);
		const std::string patternCueText = Read_Text(
			CValtanPatternEffectCueDocument::Resolve_Path());
		BOSS_PATTERN_ANIMATION_BINDING_DOCUMENT productAnimationBindings;
		const std::string productAnimationBindingText = Read_Text(
			CValtanPatternAnimationBindingDocument::Resolve_Path("Valtan"));
		const bool_t productAnimationBindingsLoaded =
			!productAnimationBindingText.empty() &&
			CValtanPatternAnimationBindingDocument::Parse_Text(
				productAnimationBindingText, productAnimationBindings, status);
		const auto whirlwindBinding = productAnimationBindingsLoaded ?
			std::find_if(productAnimationBindings.Bindings.begin(),
				productAnimationBindings.Bindings.end(),
				[](const BOSS_PATTERN_ANIMATION_BINDING& binding)
				{
					return binding.strActionId ==
						"valtan.attack.whirlwind.active";
				}) : productAnimationBindings.Bindings.end();
		const bool_t whirlwindOccurrenceLoops =
			productAnimationBindingsLoaded &&
			whirlwindBinding != productAnimationBindings.Bindings.end() &&
			1u == whirlwindBinding->Clips.size() &&
			whirlwindBinding->Clips.front().bLoop &&
			whirlwindBinding->Clips.front().strClipOccurrenceId ==
				"valtan.attack.whirlwind.active.clip.01";
		const auto whirlwindCue = patternCuesLoaded ?
			std::find_if(patternCueDocument.Cues.begin(),
				patternCueDocument.Cues.end(),
				[](const VALTAN_PATTERN_EFFECT_CUE& cue)
				{
					return cue.strActionId ==
						"valtan.attack.whirlwind.active";
				}) : patternCueDocument.Cues.end();
		runner.Require(whirlwindOccurrenceLoops &&
			whirlwindCue != patternCueDocument.Cues.end() &&
			whirlwindCue->eRepeatPolicy ==
				VALTAN_PATTERN_EFFECT_REPEAT_POLICY::ONCE &&
			!whirlwindCue->bHasSourceEnd,
			"Valtan Whirlwind Loop Occurrence Spawns Its Natural Baked Effect Once");

		const std::string sharedTargetCueText =
			"{\"schema\":\"lostark.valtan-pattern-effect-cues\","
			"\"formatVersion\":2,\"ownerArchetypeId\":\"BOSS_VALTAN\","
			"\"cues\":["
			"{\"bindingId\":\"test.cue.whirlwind.once\","
			"\"occurrenceId\":\"test.cue.whirlwind.once.occurrence.01\","
			"\"patternId\":\"VALTAN_WHIRLWIND\",\"stageId\":\"SPIN\","
			"\"actionId\":\"valtan.attack.whirlwind.active\","
			"\"clipOccurrenceId\":\"valtan.attack.whirlwind.active.clip.01\","
			"\"effectAssetId\":\"effect.valtan.test.shared-target\","
			"\"anchorSlotId\":\"root\",\"followPolicy\":\"follow\","
			"\"stopPolicy\":\"natural\",\"repeatPolicy\":\"once\","
			"\"sourceStartMs\":0,\"sourceEndMs\":null,"
			"\"localTransform\":{\"position\":[0,0,0],"
			"\"rotationDegrees\":[0,0,0],\"scale\":[1,1,1]}},"
			"{\"bindingId\":\"test.cue.whirlwind.each-loop\","
			"\"occurrenceId\":\"test.cue.whirlwind.each-loop.occurrence.01\","
			"\"patternId\":\"VALTAN_WHIRLWIND\",\"stageId\":\"SPIN\","
			"\"actionId\":\"valtan.attack.whirlwind.active\","
			"\"clipOccurrenceId\":\"valtan.attack.whirlwind.active.clip.01\","
			"\"effectAssetId\":\"effect.valtan.test.shared-target\","
			"\"anchorSlotId\":\"root\",\"followPolicy\":\"follow\","
			"\"stopPolicy\":\"natural\",\"repeatPolicy\":\"each_loop\","
			"\"sourceStartMs\":0,\"sourceEndMs\":null,"
			"\"localTransform\":{\"position\":[0,0,0],"
			"\"rotationDegrees\":[0,0,0],\"scale\":[1,1,1]}}]}";
		VALTAN_PATTERN_EFFECT_CUE_DOCUMENT sharedTargetCues;
		const bool_t sharedTargetCuesParsed = encounterLoaded &&
			productAnimationBindingsLoaded &&
			CValtanPatternEffectCueDocument::Parse_Text(
				sharedTargetCueText, encounter, productAnimationBindings,
				sharedTargetCues, status);
		runner.Require(sharedTargetCuesParsed &&
			2u == sharedTargetCues.Cues.size() &&
			sharedTargetCues.Cues[0].strEffectAssetId ==
				sharedTargetCues.Cues[1].strEffectAssetId &&
			sharedTargetCues.Cues[0].eRepeatPolicy !=
				sharedTargetCues.Cues[1].eRepeatPolicy,
			"Valtan Cue V2 Allows Same-Stage Occurrences And Shared Effect Target With Once Or Each-Loop Policy");

		auto boundedAnimationBindings = productAnimationBindings;
		if (productAnimationBindingsLoaded &&
			whirlwindBinding != productAnimationBindings.Bindings.end())
		{
			const size_t bindingIndex = static_cast<size_t>(
				whirlwindBinding - productAnimationBindings.Bindings.begin());
			boundedAnimationBindings.Bindings[bindingIndex].Clips.front().iPlayMs =
				100u;
		}
		const std::string outOfRangeCueText =
			"{\"schema\":\"lostark.valtan-pattern-effect-cues\","
			"\"formatVersion\":2,\"ownerArchetypeId\":\"BOSS_VALTAN\","
			"\"cues\":[{\"bindingId\":\"test.cue.out-of-range\","
			"\"occurrenceId\":\"test.cue.out-of-range.occurrence.01\","
			"\"patternId\":\"VALTAN_WHIRLWIND\",\"stageId\":\"SPIN\","
			"\"actionId\":\"valtan.attack.whirlwind.active\","
			"\"clipOccurrenceId\":\"valtan.attack.whirlwind.active.clip.01\","
			"\"effectAssetId\":\"effect.valtan.test.out-of-range\","
			"\"anchorSlotId\":\"root\",\"followPolicy\":\"follow\","
			"\"stopPolicy\":\"natural\",\"repeatPolicy\":\"once\","
			"\"sourceStartMs\":100,\"sourceEndMs\":null,"
			"\"localTransform\":{\"position\":[0,0,0],"
			"\"rotationDegrees\":[0,0,0],\"scale\":[1,1,1]}}]}";
		VALTAN_PATTERN_EFFECT_CUE_DOCUMENT rejectedOutOfRange =
			patternCueDocument;
		const size_t preservedCueCount = rejectedOutOfRange.Cues.size();
		runner.Require(encounterLoaded && productAnimationBindingsLoaded &&
			whirlwindOccurrenceLoops &&
			!CValtanPatternEffectCueDocument::Parse_Text(
				outOfRangeCueText, encounter, boundedAnimationBindings,
				rejectedOutOfRange, status) &&
			rejectedOutOfRange.Cues.size() == preservedCueCount,
			"Valtan Cue V2 Rejects A Source Window Outside Its Clip Segment And Preserves Prior State");
		VALTAN_PATTERN_EFFECT_CUE_DOCUMENT preservedPatternCues =
			patternCueDocument;
		const std::string preservedFirstBinding =
			preservedPatternCues.Cues.empty() ? std::string{} :
			preservedPatternCues.Cues.front().strBindingId;
		const std::string invalidPatternCueText =
			patternCueText.empty() ? std::string{} :
			patternCueText.substr(0u, patternCueText.find_last_of('}')) +
			",\n  \"unexpected\": true\n}\n";
		runner.Require(encounterLoaded && !invalidPatternCueText.empty() &&
			!CValtanPatternEffectCueDocument::Parse_Text(
				invalidPatternCueText, encounter, preservedPatternCues, status) &&
			preservedPatternCues.Cues.size() ==
				patternCueDocument.Cues.size() &&
			!preservedPatternCues.Cues.empty() &&
			preservedPatternCues.Cues.front().strBindingId ==
				preservedFirstBinding,
			"Valtan Pattern Effect Cue Parse Failure Preserves Prior Committed Document");

	}

	void Test_ValtanG04OutcomePresentationBindings(TEST_RUNNER& runner)
	{
		using namespace Client;
		const std::string text = Read_Text(
			CValtanPatternAnimationBindingDocument::Resolve_Path("Valtan"));
		BOSS_PATTERN_ANIMATION_BINDING_DOCUMENT document;
		std::string status;
		const bool_t parsed =
			CValtanPatternAnimationBindingDocument::Parse_Text(
				text, document, status);
		const std::vector<std::string> requiredActionIds = {
			"valtan.mechanic.magic-orb-stagger-76.groggy",
			"valtan.mechanic.magic-orb-stagger-76.wipe",
			"valtan.reactive.parry.normal-slash" };
		runner.Require(parsed &&
			CValtanPatternAnimationBindingDocument::Validate_RequiredActions(
				document, requiredActionIds, status),
			"Valtan G04 Outcome Actions Have One Required Presentation Binding");

		struct EXPECTED_BINDING final
		{
			std::string_view strActionId;
			std::string_view strClipName;
		};
		const std::array<EXPECTED_BINDING, 3u> expectedBindings = {{
			{ "valtan.mechanic.magic-orb-stagger-76.groggy",
				"mesh_dmg_parts_loop_1" },
			{ "valtan.mechanic.magic-orb-stagger-76.wipe",
				"mesh_att_battle_5_02_end" },
			{ "valtan.reactive.parry.normal-slash",
				"mesh_att_battle_9_01_loop" }
		}};
		bool_t clipsExact = parsed;
		for (const EXPECTED_BINDING& expected : expectedBindings)
		{
			const auto binding = std::find_if(
				document.Bindings.begin(), document.Bindings.end(),
				[&expected](const BOSS_PATTERN_ANIMATION_BINDING& candidate)
				{
					return candidate.strActionId == expected.strActionId;
				});
			clipsExact = clipsExact && binding != document.Bindings.end() &&
				1u == binding->Clips.size() &&
				binding->Clips.front() == expected.strClipName;
		}
		runner.Require(clipsExact,
			"Valtan G04 Outcome Actions Reuse The Reviewed Groggy Wipe And Parry Clips");

		CEncounterPatternReference encounter;
		std::string encounterStatus;
		const bool_t encounterLoaded = encounter.Load(
			CProjectDataRoot::Resolve(
				"Encounters/Valtan/ValtanEncounter.json"),
			encounterStatus);
		struct EXPECTED_OUTCOME_STAGE final
		{
			std::string_view strPatternId;
			std::string_view strStageId;
			std::string_view strActionId;
		};
		const std::array<EXPECTED_OUTCOME_STAGE, 3u> expectedOutcomeStages = {{
			{ "VALTAN_PARRY", "NORMAL_SLASH",
				"valtan.reactive.parry.normal-slash" },
			{ "VALTAN_MAGIC_ORB_STAGGER_76", "GROGGY",
				"valtan.mechanic.magic-orb-stagger-76.groggy" },
			{ "VALTAN_MAGIC_ORB_STAGGER_76", "WIPE",
				"valtan.mechanic.magic-orb-stagger-76.wipe" }
		}};
		size_t stageCount = 0u;
		bool_t outcomeStageJoinExact = encounterLoaded && parsed &&
			33u == encounter.Get_Patterns().size();
		for (const ENCOUNTER_PATTERN_REFERENCE& pattern :
			encounter.Get_Patterns())
		{
			stageCount += pattern.stages.size();
		}
		for (const EXPECTED_OUTCOME_STAGE& expected : expectedOutcomeStages)
		{
			size_t exactStageCount = 0u;
			for (const ENCOUNTER_PATTERN_REFERENCE& pattern :
				encounter.Get_Patterns())
			{
				if (pattern.patternId != expected.strPatternId)
					continue;
				for (const ENCOUNTER_STAGE_REFERENCE& stage : pattern.stages)
				{
					if (stage.stageId != expected.strStageId)
						continue;
					++exactStageCount;
					outcomeStageJoinExact = outcomeStageJoinExact &&
						stage.actionId == expected.strActionId &&
						stage.stageKind == "ACTIVE";
				}
			}
			outcomeStageJoinExact = outcomeStageJoinExact &&
				1u == exactStageCount;
		}
		runner.Require(outcomeStageJoinExact && 130u == stageCount,
			"Valtan G04 Outcome Presentation Bindings Join Three Current Encounter Stages By Stable Action ID");

		auto duplicate = document;
		if (!duplicate.Bindings.empty())
		{
			const auto required = std::find_if(
				duplicate.Bindings.begin(), duplicate.Bindings.end(),
				[&requiredActionIds](const BOSS_PATTERN_ANIMATION_BINDING& binding)
				{
					return binding.strActionId == requiredActionIds.front();
				});
			if (required != duplicate.Bindings.end())
				duplicate.Bindings.push_back(*required);
		}
		runner.Require(parsed &&
			!CValtanPatternAnimationBindingDocument::Validate_RequiredActions(
				duplicate, requiredActionIds, status),
			"Valtan G04 Required Outcome Contract Rejects Duplicate Binding");

		auto missing = document;
		missing.Bindings.erase(std::remove_if(
			missing.Bindings.begin(), missing.Bindings.end(),
			[&requiredActionIds](const BOSS_PATTERN_ANIMATION_BINDING& binding)
			{
				return binding.strActionId == requiredActionIds.back();
			}), missing.Bindings.end());
		runner.Require(parsed &&
			!CValtanPatternAnimationBindingDocument::Validate_RequiredActions(
				missing, requiredActionIds, status),
			"Valtan G04 Required Outcome Contract Rejects Missing Binding");
	}

	void Test_ValtanBossCombatPresentationProjection(TEST_RUNNER& runner)
	{
		using namespace Client;
		using namespace LostArk::Shared;

		CCombatHUDViewModel& hud = CCombatHUDViewModel::Get();
		hud.Reset_RuntimeState();
		WORLD_ENTITY_SNAPSHOT snapshot{};
		snapshot.iCurrentHp = 730u;
		snapshot.iMaximumHp = 1000u;
		snapshot.iPhase = 2u;
		snapshot.hasBossCombatState = true;
		snapshot.BossCombat.iStateRevision = 9u;
		snapshot.BossCombat.iAlivePartMask = 0x1u;
		snapshot.BossCombat.iFlags =
			static_cast<std::uint16_t>(BOSS_COMBAT_STATE_FLAG::SHIELDED) |
			static_cast<std::uint16_t>(BOSS_COMBAT_STATE_FLAG::COUNTERABLE) |
			static_cast<std::uint16_t>(BOSS_COMBAT_STATE_FLAG::GROGGY);
		snapshot.BossCombat.iCurrentStagger = 75u;
		snapshot.BossCombat.iMaximumStagger = 100u;
		snapshot.BossCombat.iCurrentShield = 250u;
		snapshot.BossCombat.iMaximumShield = 400u;
		snapshot.BossCombat.iGameplayPhase = 2u;
		snapshot.strPatternId = "VALTAN_MAGIC_ORB_STAGGER_76";
		snapshot.strActionId =
			"valtan.mechanic.magic-orb-stagger-76.window";
		snapshot.iPatternSequence = 4u;
		snapshot.iPatternStageIndex = 1u;
		hud.Apply_Boss("BOSS_VALTAN", snapshot);

		const HUD_BOSS_STATE first = hud.Get_Boss();
		runner.Require(first.isValid && first.iPhase == 2u &&
			first.iBossCombatStateRevision == 9u &&
			first.iAlivePartMask == 0x1u &&
			first.iBossCombatFlags == snapshot.BossCombat.iFlags &&
			first.iCurrentStagger == 75u &&
			first.iMaximumStagger == 100u &&
			first.iCurrentShield == 250u &&
			first.iMaximumShield == 400u,
			"Valtan HUD Projects Boss Flags Part Stagger Shield And Phase Exactly");

		snapshot.iPhase = 3u;
		snapshot.BossCombat.iStateRevision = 10u;
		snapshot.BossCombat.iAlivePartMask = 0u;
		snapshot.BossCombat.iFlags = static_cast<std::uint16_t>(
			BOSS_COMBAT_STATE_FLAG::INVULNERABLE);
		snapshot.BossCombat.iCurrentStagger = 0u;
		snapshot.BossCombat.iMaximumStagger = 0u;
		snapshot.BossCombat.iCurrentShield = 0u;
		snapshot.BossCombat.iMaximumShield = 0u;
		snapshot.BossCombat.iGameplayPhase = 3u;
		hud.Apply_Boss("BOSS_VALTAN", snapshot);
		const HUD_BOSS_STATE cleared = hud.Get_Boss();
		runner.Require(cleared.iBossCombatStateRevision == 10u &&
			cleared.iPhase == 3u && cleared.iAlivePartMask == 0u &&
			cleared.iBossCombatFlags == static_cast<std::uint16_t>(
				BOSS_COMBAT_STATE_FLAG::INVULNERABLE) &&
			cleared.iCurrentStagger == 0u &&
			cleared.iMaximumStagger == 0u &&
			cleared.iCurrentShield == 0u && cleared.iMaximumShield == 0u,
			"Valtan HUD Clears Stagger And Shield From The Next Persistent Snapshot");
		hud.Reset_RuntimeState();
		runner.Require(!hud.Get_Boss().isValid &&
			0u == hud.Get_Boss().iBossCombatStateRevision,
			"Valtan HUD Runtime Reset Drops Persistent Boss Presentation State");

		const std::filesystem::path repositoryRoot =
			CProjectDataRoot::Get().parent_path();
		const std::string valtanSource = Read_Text(repositoryRoot /
			"Client" / "Private" / "Valtan.cpp");
		const std::string replicationSource = Read_Text(repositoryRoot /
			"Client" / "Private" / "ClientReplication.cpp");
		const std::array<std::string_view, 7u> stateContractTokens = {{
			"state.iStateRevision < m_BossCombatState.iStateRevision",
			"state.iStateRevision == m_BossCombatState.iStateRevision",
			"return Is_SameBossCombatState(state, m_BossCombatState)",
			"state.iAlivePartMask & stateMask",
			"Set_ArmorPartVisible",
			"event.iEventSequence <= m_iLastBossCombatEventSequence",
			"m_iLastBossCombatEventSequence = event.iEventSequence"
		}};
		const bool_t valtanStateContractExact = !valtanSource.empty() &&
			std::all_of(stateContractTokens.begin(), stateContractTokens.end(),
				[&valtanSource](const std::string_view token)
				{
					return std::string::npos != valtanSource.find(token);
				});
		runner.Require(valtanStateContractExact &&
			replicationSource.find(
				"Apply_BossCombatState(entity.BossCombat)") !=
					std::string::npos &&
			replicationSource.find("Apply_BossCombatEvent(event)") !=
					std::string::npos,
			"Valtan Source Keeps Revision Regression Part Projection And Event Deduplication");
	}

	void Test_ValtanCombatObjectProjection(TEST_RUNNER& runner)
	{
		using namespace Client;
		using namespace LostArk::Shared;
		SCOPED_ENVIRONMENT_VARIABLE runtimeResourceRootScope(
			L"LOSTARK_RESOURCE_ROOT");
		std::filesystem::path expectedRuntimeResourceRoot =
			(CProjectDataRoot::Get().parent_path() / L"Client" / L"Bin" /
			 L"Resources").lexically_normal();
		std::error_code physicalModelError;
		const std::filesystem::path physicalValtanWeapon =
			std::filesystem::weakly_canonical(
				expectedRuntimeResourceRoot / L"Character" / L"Valtan" /
					L"ValtanWeapon.wmodel",
				physicalModelError);
		if (!physicalModelError &&
			std::filesystem::is_regular_file(physicalValtanWeapon))
		{
			expectedRuntimeResourceRoot = physicalValtanWeapon.parent_path().
				parent_path().parent_path();
		}
		runtimeResourceRootScope.Set(expectedRuntimeResourceRoot.c_str());

		struct PROJECTION_SINK final
		{
			uint32_t iSpawnFailuresRemaining = 0u;
			bool_t bFailNextUpdate = false;
			uint64_t iNextHandle = 1u;
			std::vector<S2C_COMBAT_OBJECT_SPAWNED> Spawns;
			std::vector<std::pair<uint64_t, COMBAT_OBJECT_SNAPSHOT>> Updates;
			std::vector<uint64_t> Stops;

			bool_t Spawn(const S2C_COMBAT_OBJECT_SPAWNED& message,
				uint64_t& outHandle, std::string& outStatus)
			{
				Spawns.push_back(message);
				if (0u != iSpawnFailuresRemaining)
				{
					--iSpawnFailuresRemaining;
					outHandle = 0u;
					outStatus = "injected visual admission failure";
					return false;
				}
				outHandle = iNextHandle++;
				outStatus.clear();
				return true;
			}

			bool_t Update(const uint64_t handle,
				const COMBAT_OBJECT_SNAPSHOT& snapshot)
			{
				Updates.emplace_back(handle, snapshot);
				if (!bFailNextUpdate)
					return true;
				bFailNextUpdate = false;
				return false;
			}

			void Stop(const uint64_t handle)
			{
				Stops.push_back(handle);
			}
		};

		const auto MakeSpawn = [](
			const COMBAT_OBJECT_ID objectId,
			const NET_ENTITY_ID sourceId,
			const uint32_t spawnTick,
			const uint32_t serverTick,
			const char_t* archetypeId,
			const char_t* visualId)
		{
			S2C_COMBAT_OBJECT_SPAWNED message{};
			message.iCombatObjectId = objectId;
			message.iSourceNetEntityId = sourceId;
			message.iSpawnTick = spawnTick;
			message.iServerTick = serverTick;
			message.strCombatObjectArchetypeId = archetypeId;
			message.strClientVisualId = visualId;
			message.fPositionX = 10.f;
			message.fPositionY = 2.f;
			message.fPositionZ = -4.f;
			message.fYawDegrees = 45.f;
			return message;
		};
		const auto MakeSnapshot = [](const S2C_COMBAT_OBJECT_SPAWNED& spawn)
		{
			COMBAT_OBJECT_SNAPSHOT snapshot{};
			snapshot.iCombatObjectId = spawn.iCombatObjectId;
			snapshot.iSourceNetEntityId = spawn.iSourceNetEntityId;
			snapshot.fPositionX = spawn.fPositionX;
			snapshot.fPositionY = spawn.fPositionY;
			snapshot.fPositionZ = spawn.fPositionZ;
			snapshot.fYawDegrees = spawn.fYawDegrees;
			return snapshot;
		};

		std::string status;
		CCombatObjectProjectionRuntime lifecycle;
		PROJECTION_SINK lifecycleSink;
		const S2C_COMBAT_OBJECT_SPAWNED lateJoinSpawn = MakeSpawn(
			10u, 100u, 70u, 100u,
			"combatobject.valtan.high-jump.target-axe",
			"combatobject.visual.valtan.high-jump.target-axe.v1");
		const bool_t spawned = lifecycle.Apply_Spawn(
			lateJoinSpawn, lifecycleSink, status);
		const bool_t duplicateIgnored = lifecycle.Apply_Spawn(
			lateJoinSpawn, lifecycleSink, status);
		S2C_COMBAT_OBJECT_SPAWNED conflicting = lateJoinSpawn;
		conflicting.strClientVisualId =
			"combatobject.visual.valtan.red-blade-wave.projectile.v1";
		const bool_t conflictRejected =
			!lifecycle.Apply_Spawn(conflicting, lifecycleSink, status);
		COMBAT_OBJECT_SNAPSHOT moved = MakeSnapshot(lateJoinSpawn);
		moved.fPositionX = 12.f;
		const bool_t snapshotApplied = lifecycle.Apply_Snapshot(
			101u, { moved }, lifecycleSink, status);
		float lateJoinAgeSeconds = 0.f;
		const bool_t lateJoinAgeResolved =
			CActionPresentationTimeline::Try_ResolveActionAgeSeconds(
				lateJoinSpawn.iServerTick, lateJoinSpawn.iSpawnTick,
				30.f, lateJoinAgeSeconds);
		S2C_COMBAT_OBJECT_DESPAWNED despawn{};
		despawn.iCombatObjectId = lateJoinSpawn.iCombatObjectId;
		const bool_t despawned = lifecycle.Apply_Despawn(
			despawn, lifecycleSink, status);
		runner.Require(spawned && duplicateIgnored && conflictRejected &&
			snapshotApplied && despawned && lifecycle.Get_Count() == 0u &&
			lifecycleSink.Spawns.size() == 1u &&
			lifecycleSink.Updates.size() == 1u &&
			lifecycleSink.Stops == std::vector<uint64_t>{ 1u } &&
			lateJoinAgeResolved && std::abs(lateJoinAgeSeconds - 1.f) < 1.0e-6f &&
			lifecycleSink.Spawns.front().iServerTick == 100u &&
			lifecycleSink.Spawns.front().iSpawnTick == 70u,
			"Valtan Combat Object Lifecycle Deduplicates Spawn Updates World Root Seeks Late Join Age And Stops Once");

		CCombatObjectProjectionRuntime atomic;
		PROJECTION_SINK atomicSink;
		const S2C_COMBAT_OBJECT_SPAWNED first = MakeSpawn(
			20u, 200u, 200u, 200u,
			"combatobject.valtan.high-jump.target-axe",
			"combatobject.visual.valtan.high-jump.target-axe.v1");
		const S2C_COMBAT_OBJECT_SPAWNED second = MakeSpawn(
			21u, 200u, 200u, 200u,
			"combatobject.valtan.red-blade-wave.projectile",
			"combatobject.visual.valtan.red-blade-wave.projectile.v1");
		const bool_t atomicSpawned = atomic.Apply_Spawn(first, atomicSink, status) &&
			atomic.Apply_Spawn(second, atomicSink, status);
		const COMBAT_OBJECT_PROJECTION_RECORD* beforeFirst = atomic.Find(20u);
		const bool_t beforeFirstPresent = nullptr != beforeFirst;
		const float beforeFirstPositionX = beforeFirstPresent ?
			beforeFirst->Snapshot.fPositionX : 0.f;
		COMBAT_OBJECT_SNAPSHOT unknown = MakeSnapshot(second);
		unknown.iCombatObjectId = 22u;
		atomicSink.Updates.clear();
		const bool_t unknownSetRejected = !atomic.Apply_Snapshot(
			201u, { MakeSnapshot(first), unknown }, atomicSink, status);
		const COMBAT_OBJECT_PROJECTION_RECORD* afterFirst = atomic.Find(20u);
		runner.Require(atomicSpawned && unknownSetRejected &&
			atomicSink.Updates.empty() && beforeFirstPresent &&
			nullptr != afterFirst &&
			afterFirst->Snapshot.fPositionX == beforeFirstPositionX &&
			atomic.Get_Count() == 2u,
			"Valtan Combat Object Full Snapshot Rejects Unknown Set Atomically Before Presentation Updates");
		atomic.Reset(atomicSink);

		CCombatObjectProjectionRuntime wrappedRetry;
		PROJECTION_SINK retrySink;
		retrySink.iSpawnFailuresRemaining = 3u;
		const uint32_t wrapSpawnTick =
			(std::numeric_limits<uint32_t>::max)() - 29u;
		const S2C_COMBAT_OBJECT_SPAWNED retrySpawn = MakeSpawn(
			30u, 300u, wrapSpawnTick, wrapSpawnTick,
			"combatobject.valtan.high-jump.target-axe",
			"combatobject.visual.valtan.high-jump.target-axe.v1");
		const COMBAT_OBJECT_SNAPSHOT retrySnapshot = MakeSnapshot(retrySpawn);
		const bool_t logicalSpawnKept = wrappedRetry.Apply_Spawn(
			retrySpawn, retrySink, status);
		const bool_t beforeWrapNoRetry = wrappedRetry.Apply_Snapshot(
			(std::numeric_limits<uint32_t>::max)(), { retrySnapshot },
			retrySink, status) && retrySink.Spawns.size() == 1u;
		const bool_t firstRetryAtOne = wrappedRetry.Apply_Snapshot(
			1u, { retrySnapshot }, retrySink, status) &&
			retrySink.Spawns.size() == 2u;
		const bool_t noPerSnapshotRetry = wrappedRetry.Apply_Snapshot(
			2u, { retrySnapshot }, retrySink, status) &&
			retrySink.Spawns.size() == 2u;
		const bool_t thirdAttemptAtThirtyOne = wrappedRetry.Apply_Snapshot(
			31u, { retrySnapshot }, retrySink, status) &&
			retrySink.Spawns.size() == 3u;
		const bool_t boundedAfterThirdFailure = wrappedRetry.Apply_Snapshot(
			61u, { retrySnapshot }, retrySink, status) &&
			retrySink.Spawns.size() == 3u;
		const COMBAT_OBJECT_PROJECTION_RECORD* retryRecord =
			wrappedRetry.Find(retrySpawn.iCombatObjectId);
		runner.Require(logicalSpawnKept && beforeWrapNoRetry &&
			firstRetryAtOne && noPerSnapshotRetry &&
			thirdAttemptAtThirtyOne && boundedAfterThirdFailure &&
			nullptr != retryRecord && 0u == retryRecord->iPresentationHandle &&
			retryRecord->iPresentationAttemptCount == 3u,
			"Valtan Combat Object Visual Admission Retry Skips Wrapped Zero Waits Thirty Ticks And Stops After Three Attempts");

		CCombatObjectProjectionRuntime updateRetry;
		PROJECTION_SINK updateSink;
		const S2C_COMBAT_OBJECT_SPAWNED updateSpawn = MakeSpawn(
			40u, 400u, 100u, 100u,
			"combatobject.valtan.red-blade-wave.projectile",
			"combatobject.visual.valtan.red-blade-wave.projectile.v1");
		const COMBAT_OBJECT_SNAPSHOT updateSnapshot = MakeSnapshot(updateSpawn);
		const bool_t updateSpawned = updateRetry.Apply_Spawn(
			updateSpawn, updateSink, status);
		updateSink.bFailNextUpdate = true;
		const bool_t updateFailureKeptLogical = updateRetry.Apply_Snapshot(
			101u, { updateSnapshot }, updateSink, status);
		const bool_t updateFailureDidNotRetryNextFrame =
			updateRetry.Apply_Snapshot(
				102u, { updateSnapshot }, updateSink, status) &&
			updateSink.Spawns.size() == 1u;
		const bool_t updateRetriedAtDeadline = updateRetry.Apply_Snapshot(
			131u, { updateSnapshot }, updateSink, status) &&
			updateSink.Spawns.size() == 2u;
		const COMBAT_OBJECT_PROJECTION_RECORD* updatedRecord =
			updateRetry.Find(updateSpawn.iCombatObjectId);
		const bool_t replacementHandleLive = nullptr != updatedRecord &&
			0u != updatedRecord->iPresentationHandle;
		updateRetry.Reset(updateSink);
		runner.Require(updateSpawned && updateFailureKeptLogical &&
			updateFailureDidNotRetryNextFrame && updateRetriedAtDeadline &&
			replacementHandleLive &&
			updateSink.Stops.size() == 2u && updateRetry.Get_Count() == 0u,
			"Valtan Combat Object Root Update Failure Stops The Handle Schedules One Bounded Retry And Reset Stops The Replacement");

		const std::filesystem::path repositoryRoot =
			CProjectDataRoot::Get().parent_path();
		const BOSS_ACTOR_ENTRY* boss = CActorCatalog::Find_Boss("BOSS_VALTAN");
		std::set<std::string, std::less<>> productEffects;
		VALTAN_PATTERN_EFFECT_CUE_DOCUMENT cueDocument;
		std::string cueStatus;
		const bool_t cuesLoaded = CValtanPatternEffectCueDocument::Load_Source(
			cueDocument, cueStatus);
		for (const VALTAN_PATTERN_EFFECT_CUE& cue : cueDocument.Cues)
			productEffects.insert(cue.strEffectAssetId);
		if (nullptr != boss)
		{
			for (const BOSS_COMBAT_OBJECT_VISUAL_ENTRY& visual :
				boss->combatObjectVisuals)
			{
				productEffects.insert(visual.effectAssetId);
			}
		}
		const BOSS_COMBAT_OBJECT_VISUAL_ENTRY* skyVisual =
			CActorCatalog::Find_BossCombatObjectVisual(
				"BOSS_VALTAN",
				"combatobject.valtan.high-jump.target-axe",
				"combatobject.visual.valtan.high-jump.target-axe.v1");
		const BOSS_COMBAT_OBJECT_VISUAL_ENTRY* bladeVisual =
			CActorCatalog::Find_BossCombatObjectVisual(
				"BOSS_VALTAN",
				"combatobject.valtan.red-blade-wave.projectile",
				"combatobject.visual.valtan.red-blade-wave.projectile.v1");
		const bool_t prewarmContractExact =
			cuesLoaded && cueDocument.Cues.size() == 106u &&
			nullptr != boss && boss->combatObjectVisuals.size() == 2u &&
			nullptr != skyVisual && nullptr != bladeVisual &&
			skyVisual->effectAssetId == "effect.valtan.sky-axe.active" &&
			bladeVisual->effectAssetId == "effect.valtan.red-blade-wave.active" &&
			productEffects.size() == 108u &&
			!std::any_of(cueDocument.Cues.begin(), cueDocument.Cues.end(),
				[](const VALTAN_PATTERN_EFFECT_CUE& cue)
				{
					return cue.strActionId ==
							"valtan.attack.red-blade-wave.active" ||
						cue.strActionId ==
							"valtan.attack.high-jump.airborne" ||
						cue.strEffectAssetId ==
							"effect.valtan.red-blade-wave.active" ||
						cue.strEffectAssetId ==
							"effect.valtan.high-jump.airborne";
				});
		if (!prewarmContractExact)
		{
			std::cout << "[DETAIL] Valtan combat-object prewarm: cueStatus=" <<
				cueStatus << " actorStatus=" << CActorCatalog::Get_Status() <<
				" cueCount=" << cueDocument.Cues.size() <<
				" productCount=" << productEffects.size() << '\n';
		}
		runner.Require(prewarmContractExact,
			"Valtan Product Prewarm Owns 106 Boss-Root Cues Plus Two Single-Owner Moving Combat-Object Effects");

		VALTAN_PATTERN_TREE_VIEW patternTree;
		std::string patternTreeStatus;
		const bool_t patternTreeLoaded = CValtanPatternTree::Load(
			patternTree, patternTreeStatus);
		const auto FindStage = [&patternTree](
			const std::string_view patternId,
			const std::string_view actionId) -> const VALTAN_STAGE_VIEW*
			{
				const auto FindIn = [patternId, actionId](
					const std::vector<VALTAN_PATTERN_VIEW>& patterns)
					-> const VALTAN_STAGE_VIEW*
					{
						for (const VALTAN_PATTERN_VIEW& pattern : patterns)
						{
							if (pattern.strPatternId != patternId)
								continue;
							for (const VALTAN_STAGE_VIEW& stage : pattern.Stages)
							{
								if (stage.strActionId == actionId)
									return &stage;
							}
						}
						return nullptr;
					};
				if (const VALTAN_STAGE_VIEW* stage =
						FindIn(patternTree.Gimmicks))
				{
					return stage;
				}
				return FindIn(patternTree.Rotation);
			};
		const VALTAN_STAGE_VIEW* highJumpAirborne = patternTreeLoaded ?
			FindStage("VALTAN_HIGH_JUMP",
				"valtan.attack.high-jump.airborne") : nullptr;
		const VALTAN_STAGE_VIEW* redBladeProjectile = patternTreeLoaded ?
			FindStage("VALTAN_RED_BLADE_WAVE",
				"valtan.attack.red-blade-wave.active") : nullptr;
		const auto HasCombatVisual = [](
			const VALTAN_STAGE_VIEW* stage,
			const std::string_view archetypeId,
			const std::string_view visualId,
			const std::string_view effectAssetId)
			{
				return nullptr != stage && stage->ProductCues.empty() &&
					stage->CombatObjectEffects.size() == 1u &&
					stage->CombatObjectEffects.front().
						strCombatObjectArchetypeId == archetypeId &&
					stage->CombatObjectEffects.front().strClientVisualId ==
						visualId &&
					stage->CombatObjectEffects.front().strEffectAssetId ==
						effectAssetId;
			};
		const bool_t patternTreeContractExact =
			patternTreeLoaded && patternTree.Get_PatternCount() == 33u &&
			patternTree.Get_StageCount() == 130u &&
			patternTree.Get_ClipOccurrenceCount() == 137u &&
			patternTree.Get_ProductCueStageCount() == 98u &&
			patternTree.Get_ProductCueCount() == 106u &&
			patternTree.Get_CombatObjectEffectCount() == 2u &&
			HasCombatVisual(highJumpAirborne,
				"combatobject.valtan.high-jump.target-axe",
				"combatobject.visual.valtan.high-jump.target-axe.v1",
				"effect.valtan.sky-axe.active") &&
			HasCombatVisual(redBladeProjectile,
				"combatobject.valtan.red-blade-wave.projectile",
				"combatobject.visual.valtan.red-blade-wave.projectile.v1",
				"effect.valtan.red-blade-wave.active");
		if (!patternTreeContractExact)
		{
			std::cout << "[DETAIL] Valtan pattern tree combat-object join: " <<
				patternTreeStatus << " patterns=" <<
				patternTree.Get_PatternCount() << " stages=" <<
				patternTree.Get_StageCount() << " clips=" <<
				patternTree.Get_ClipOccurrenceCount() << " cueStages=" <<
				patternTree.Get_ProductCueStageCount() << " cues=" <<
				patternTree.Get_ProductCueCount() << " movingFx=" <<
				patternTree.Get_CombatObjectEffectCount() << '\n';
		}
		runner.Require(patternTreeContractExact,
			"Valtan All Effects Tree Places Moving Combat Objects Under Their Exact Pattern And Semantic Stage");

		EFFECT_DOCUMENT_DESC skyDocument;
		std::string skyStatus;
		const bool_t skyLoaded = CEffectDocumentCodec::Load(
			repositoryRoot / "Data" / "Effects" / "Authored" /
				"effect.valtan.sky-axe.active.effect.json",
			skyDocument, skyStatus);
		const auto FindElement = [&skyDocument](
			const std::string_view elementId) -> const EFFECT_ELEMENT_DESC*
			{
				const auto found = std::find_if(
					skyDocument.Elements.begin(), skyDocument.Elements.end(),
					[elementId](const EFFECT_ELEMENT_DESC& element)
					{
						return element.strElementId == elementId;
					});
				return found == skyDocument.Elements.end() ? nullptr : &*found;
			};
		const auto HasResource = [](
			const EFFECT_ELEMENT_DESC* element,
			const std::string_view slotId,
			const std::string_view assetId)
			{
				return nullptr != element && std::any_of(
					element->ResourceBindings.begin(),
					element->ResourceBindings.end(),
					[slotId, assetId](const EFFECT_RESOURCE_BINDING_DESC& resource)
					{
						return resource.strSlotId == slotId &&
							resource.strAssetId == assetId;
					});
			};
		const EFFECT_ELEMENT_DESC* skyMesh =
			FindElement("mesh.valtan.sky-axe.descent");
		const EFFECT_ELEMENT_DESC* skyTarget =
			FindElement("decal.valtan.sky-axe.target");
		const EFFECT_ELEMENT_DESC* skyImpact =
			FindElement("particle.valtan.sky-axe.impact");
		const bool_t skyResourceExact = nullptr != skyMesh &&
			skyMesh->ResourceBindings.size() == 1u &&
			skyMesh->ResourceBindings.front().strSlotId == "meshModel" &&
			skyMesh->ResourceBindings.front().strAssetId ==
				"Character/Valtan/ValtanWeapon.wmodel";
		EFFECT_RESOURCE_FILE_KIND resourceKind = EFFECT_RESOURCE_FILE_KIND::END;
		const bool_t characterModelAccepted =
			CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "meshModel",
				"Character/Valtan/ValtanWeapon.wmodel", &resourceKind) &&
			resourceKind == EFFECT_RESOURCE_FILE_KIND::MODEL;
		const bool_t characterModelRejectedOutsideMeshSlot =
			!CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "base",
				"Character/Valtan/ValtanWeapon.wmodel");
		const bool_t characterTextureRejected =
			!CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "meshModel",
				"Character/WP_WSWP_M_06/textures/wp_wswp_m_06s_d.dds");
		const bool_t characterEscapeRejected =
			!CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "meshModel",
				"Character/Valtan/../Valtan/ValtanWeapon.wmodel");
		const bool_t skyContractExact =
			skyLoaded && skyDocument.Elements.size() == 3u &&
			nullptr != skyMesh && nullptr != skyTarget && nullptr != skyImpact &&
			skyResourceExact &&
			skyDocument.strEffectAssetId == "effect.valtan.sky-axe.active" &&
			skyMesh->eKind == EFFECT_ELEMENT_KIND::MESH &&
			std::abs(skyMesh->Detail.Transform.vPosition.y - 15.f) < 1.0e-6f &&
			skyMesh->Detail.LinearLerp.bPosition &&
			std::abs(skyMesh->Detail.LinearLerp.vEndPosition.y) < 1.0e-6f &&
			std::abs(skyMesh->Detail.Timing.fLifeTimeSeconds - 1.2f) <
				1.0e-6f &&
			skyTarget->eKind == EFFECT_ELEMENT_KIND::DECAL &&
			HasResource(skyTarget, "base",
				"Effect/Valtan/Textures/FX_TEX_02/fx_d_atypical_032.dds") &&
			std::abs(skyTarget->Detail.Timing.fStartDelaySeconds) < 1.0e-6f &&
			std::abs(skyTarget->Detail.Timing.fLifeTimeSeconds - 1.2f) <
				1.0e-6f &&
			std::abs(skyTarget->Detail.Decal.vSize.x - 3.5f) < 1.0e-6f &&
			std::abs(skyTarget->Detail.Decal.vSize.y - 3.5f) < 1.0e-6f &&
			skyImpact->eKind == EFFECT_ELEMENT_KIND::PARTICLE &&
			HasResource(skyImpact, "base",
				"Effect/Valtan/Textures/FX_TEX_04/fx_i_shockwave_02_ycl.dds") &&
			HasResource(skyImpact, "dissolve",
				"Effect/Valtan/Textures/FX_TEX_02/fx_d_atypical_011.dds") &&
			std::abs(skyImpact->Detail.Timing.fStartDelaySeconds - 1.2f) <
				1.0e-6f &&
			std::abs(skyImpact->Detail.Timing.fLifeTimeSeconds - 0.65f) <
				1.0e-6f &&
			std::abs(skyImpact->Detail.Particle.vStartSize.x - 4.2f) <
				1.0e-6f &&
			std::abs(skyImpact->Detail.Particle.vEndSize.x - 7.5f) <
				1.0e-6f &&
			skyImpact->Detail.Timing.fStartDelaySeconds +
				skyImpact->Detail.Timing.fLifeTimeSeconds < 1.9f &&
			characterModelAccepted &&
			characterModelRejectedOutsideMeshSlot && characterTextureRejected &&
			characterEscapeRejected;
		if (!skyContractExact)
		{
			const std::filesystem::path runtimeResourceRoot =
				CRuntimeAssetRoot::Get();
			const std::filesystem::path resolvedCharacterModel =
				CRuntimeAssetRoot::Resolve(
					"Character/Valtan/ValtanWeapon.wmodel");
			std::error_code rootError;
			const std::filesystem::path canonicalRuntimeResourceRoot =
				std::filesystem::weakly_canonical(
					runtimeResourceRoot, rootError);
			std::error_code modelError;
			const std::filesystem::path canonicalCharacterModel =
				std::filesystem::weakly_canonical(
					runtimeResourceRoot /
						"Character/Valtan/ValtanWeapon.wmodel", modelError);
			std::cout << "[DETAIL] Valtan sky-axe: status=" << skyStatus <<
				" loaded=" << skyLoaded << " element=" <<
				skyDocument.Elements.size() << " resource=" << skyResourceExact <<
				" modelAccepted=" << characterModelAccepted <<
				" modelRejectedOutsideSlot=" <<
				characterModelRejectedOutsideMeshSlot <<
				" textureRejected=" << characterTextureRejected <<
				" escapeRejected=" << characterEscapeRejected <<
				" resourceRoot=" << runtimeResourceRoot.string() <<
				" canonicalRoot=" << canonicalRuntimeResourceRoot.string() <<
				" rootError=" << rootError.message() <<
				" canonicalModel=" << canonicalCharacterModel.string() <<
				" modelError=" << modelError.message() <<
				" resolved=" << resolvedCharacterModel.string() <<
				" exists=" << std::filesystem::is_regular_file(
					resolvedCharacterModel) << '\n';
		}
		runner.Require(skyContractExact,
			"Valtan Sky Axe Combat Object Owns Target Decal Official Falling Axe And Timed Sprite Impact Before Server Lifetime Ends");

		const std::string replicationSource = Read_Text(repositoryRoot /
			"Client" / "Private" / "ClientReplication.cpp");
		const std::string presentationSource = Read_Text(repositoryRoot /
			"Client" / "Private" / "Effect_PresentationService.cpp");
		const std::string publisherSource = Read_Text(repositoryRoot /
			"Tools" / "EffectPipeline" / "Publish-Effects.ps1");
		std::vector<CLIENT_REPLICATION_EVENT_TYPE> eventQueue;
		const auto enqueueEvent = [&eventQueue](
			const CLIENT_REPLICATION_EVENT_TYPE incoming)
		{
			if (!eventQueue.empty() &&
				Can_CoalesceAdjacentReplicationEvents(
					eventQueue.back(), incoming))
			{
				eventQueue.back() = incoming;
			}
			else
			{
				eventQueue.push_back(incoming);
			}
		};
		enqueueEvent(CLIENT_REPLICATION_EVENT_TYPE::COMBAT_OBJECT_SPAWNED);
		enqueueEvent(CLIENT_REPLICATION_EVENT_TYPE::WORLD_SNAPSHOT);
		enqueueEvent(CLIENT_REPLICATION_EVENT_TYPE::WORLD_SNAPSHOT);
		enqueueEvent(CLIENT_REPLICATION_EVENT_TYPE::COMBAT_OBJECT_DESPAWNED);
		enqueueEvent(CLIENT_REPLICATION_EVENT_TYPE::WORLD_SNAPSHOT);
		enqueueEvent(CLIENT_REPLICATION_EVENT_TYPE::WORLD_SNAPSHOT);
		const bool_t lifecycleBarriersExact = eventQueue.size() == 4u &&
			eventQueue[0] ==
				CLIENT_REPLICATION_EVENT_TYPE::COMBAT_OBJECT_SPAWNED &&
			eventQueue[1] == CLIENT_REPLICATION_EVENT_TYPE::WORLD_SNAPSHOT &&
			eventQueue[2] ==
				CLIENT_REPLICATION_EVENT_TYPE::COMBAT_OBJECT_DESPAWNED &&
			eventQueue[3] == CLIENT_REPLICATION_EVENT_TYPE::WORLD_SNAPSHOT &&
			Can_CoalesceAdjacentInboundFrames(
				PACKET_TYPE::S2C_WORLD_SNAPSHOT,
				PACKET_TYPE::S2C_WORLD_SNAPSHOT) &&
			!Can_CoalesceAdjacentInboundFrames(
				PACKET_TYPE::S2C_COMBAT_OBJECT_SPAWNED,
				PACKET_TYPE::S2C_WORLD_SNAPSHOT) &&
			!Can_CoalesceAdjacentInboundFrames(
				PACKET_TYPE::S2C_WORLD_SNAPSHOT,
				PACKET_TYPE::S2C_COMBAT_OBJECT_DESPAWNED);
		runner.Require(lifecycleBarriersExact,
			"Valtan Combat Object Spawn And Despawn Are Queue Barriers While Only Adjacent Full Snapshots Coalesce");
		runner.Require(replicationSource.find("spawned.iServerTick") !=
				std::string::npos &&
			replicationSource.find("spawned.iSpawnTick") !=
				std::string::npos &&
			replicationSource.find("Try_ResolveActionAgeSeconds") !=
				std::string::npos &&
			replicationSource.find(
				"desc.fInitialSampleTimeSeconds = actionAgeSeconds") !=
				std::string::npos &&
			presentationSource.find("Spawn_WorldRoot") != std::string::npos &&
			presentationSource.find("Update_WorldRoot") != std::string::npos &&
			presentationSource.find("Stop_WorldRoot") != std::string::npos &&
			publisherSource.find("Resolve-SafeElementResource") !=
				std::string::npos &&
			publisherSource.find("combatObjectVisuals") != std::string::npos &&
			publisherSource.find("cataloguedWithoutOwner") != std::string::npos,
			"Valtan Combat Object Consumer Seeks Server Age Owns A World-Root Handle And Publisher Joins BossCatalog Ownership");
	}

	void Test_ValtanPatternEffectOccurrenceScheduling(TEST_RUNNER& runner)
	{
		using namespace Client;
		std::vector<VALTAN_PATTERN_EFFECT_OCCURRENCE_SAMPLE> samples;
		VALTAN_PATTERN_EFFECT_OCCURRENCE_SCAN_DESC scan;
		scan.fCurrentActionAgeSeconds = 0.15f;
		scan.fFirstOccurrenceWallSeconds = 0.1f;
		scan.fLoopWallDurationSeconds = 0.5f;
		scan.fPlaybackRate = 1.f;
		scan.fLiveSourceDurationSeconds = 0.7f;
		scan.bEachLoop = true;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(scan, samples) &&
			1u == samples.size() && 0u == samples[0].iLoopEpoch &&
			std::abs(samples[0].fInitialSampleSeconds - 0.05f) < 0.00001f,
			"Valtan Natural Each-Loop First Snapshot Catches Up The Live Epoch");

		scan.bHasPreviousActionAge = true;
		scan.fPreviousActionAgeSeconds = 0.15f;
		scan.fCurrentActionAgeSeconds = 1.15f;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(scan, samples) &&
			2u == samples.size() &&
			1u == samples[0].iLoopEpoch &&
			2u == samples[1].iLoopEpoch &&
			std::abs(samples[0].fInitialSampleSeconds - 0.55f) < 0.00002f &&
			std::abs(samples[1].fInitialSampleSeconds - 0.05f) < 0.00002f,
			"Valtan Each-Loop Snapshot Jump Enumerates Every Crossed Live Epoch");

		scan.fLiveSourceDurationSeconds = 0.1f;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(scan, samples) &&
			1u == samples.size() && 2u == samples[0].iLoopEpoch &&
			std::abs(samples[0].fInitialSampleSeconds - 0.05f) < 0.00002f,
			"Valtan Cue-End Snapshot Jump Drops Crossed Epochs Outside Their Source Window");

		VALTAN_PATTERN_EFFECT_OCCURRENCE_SCAN_DESC once;
		once.fCurrentActionAgeSeconds = 0.3f;
		once.fFirstOccurrenceWallSeconds = 0.1f;
		once.fPlaybackRate = 1.f;
		once.fLiveSourceDurationSeconds = 0.4f;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(once, samples) &&
			1u == samples.size() &&
			std::abs(samples[0].fInitialSampleSeconds - 0.2f) < 0.00001f,
			"Valtan Once Natural First Snapshot Seeks A Still-Live Product Effect");
		once.fCurrentActionAgeSeconds = 0.5f;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(once, samples) &&
			samples.empty(),
			"Valtan Once Natural Exact Duration Boundary Is Stale");
		once.fCurrentActionAgeSeconds = 1.f;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(once, samples) &&
			samples.empty(),
			"Valtan Once Natural Stale First Snapshot Queues Zero Occurrences");

		VALTAN_PATTERN_EFFECT_OCCURRENCE_SCAN_DESC capped;
		capped.fCurrentActionAgeSeconds = 1.f;
		capped.fFirstOccurrenceWallSeconds = 0.f;
		capped.fLoopWallDurationSeconds = 0.001f;
		capped.fPlaybackRate = 1.f;
		capped.fLiveSourceDurationSeconds = 1.f;
		capped.bEachLoop = true;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(capped, samples) &&
			VALTAN_MAX_PATTERN_EFFECT_OCCURRENCES_PER_SCAN == samples.size() &&
			745u == samples.front().iLoopEpoch &&
			1000u == samples.back().iLoopEpoch,
			"Valtan Large Loop Jump Retains The Latest 256 Live Epochs Deterministically");

		capped.fPreviousActionAgeSeconds = 0.9f;
		capped.fCurrentActionAgeSeconds = 1.f;
		capped.bHasPreviousActionAge = true;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(capped, samples) &&
			100u == samples.size() && 901u == samples.front().iLoopEpoch &&
			1000u == samples.back().iLoopEpoch,
			"Valtan Subsequent Loop Scan Emits Only Crossed Epochs");
		capped.bHasPreviousActionAge = false;
		runner.Require(
			Resolve_ValtanPatternEffectOccurrenceScan(capped, samples) &&
			VALTAN_MAX_PATTERN_EFFECT_OCCURRENCES_PER_SCAN == samples.size() &&
			745u == samples.front().iLoopEpoch,
			"Valtan Stage-Edge Scan Reset Rebuilds The Bounded Live Catch-Up Set");

		capped.bHasPreviousActionAge = true;
		capped.fPreviousActionAgeSeconds = 1.2f;
		runner.Require(
			!Resolve_ValtanPatternEffectOccurrenceScan(capped, samples) &&
			samples.empty(),
			"Valtan Occurrence Scan Rejects A Backward Snapshot Interval");
	}

	/* An artist rebind is only useful if it survives the next re-materialize.
	   The compiler owns every resource binding, so the override block plus its
	   compiler baseline is what makes Save/Reload and re-import durable. */
	void Test_AuthoringOverrideOwnership(TEST_RUNNER& runner)
	{
		using namespace Client;
		struct FAMILY_CASE final
		{
			const char_t* pShape = nullptr;
			EFFECT_SOURCE_BLEND_CLASS eBlend =
				EFFECT_SOURCE_BLEND_CLASS::UNKNOWN;
			const char_t* pSubUV = nullptr;
			EFFECT_ELEMENT_KIND eKind = EFFECT_ELEMENT_KIND::PARTICLE;
			EFFECT_GENERIC_AUTHORING_FAMILY eExpected =
				EFFECT_GENERIC_AUTHORING_FAMILY::END;
		};
		const std::array<FAMILY_CASE, 13u> FamilyCases = {{
			{ "sprite", EFFECT_SOURCE_BLEND_CLASS::ADDITIVE, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::SPRITE_ADDITIVE },
			{ "sprite", EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::SPRITE_TRANSLUCENT },
			{ "mesh", EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::MESH_TRANSLUCENT },
			{ "sprite", EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT,
				"psuvim_linear_blend", EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::SPRITE_TRANSLUCENT_SUBUV },
			{ "mesh", EFFECT_SOURCE_BLEND_CLASS::ADDITIVE, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::MESH_ADDITIVE },
			{ "sprite", EFFECT_SOURCE_BLEND_CLASS::ADDITIVE,
				"psuvim_random", EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::SPRITE_ADDITIVE_SUBUV },
			{ "mesh", EFFECT_SOURCE_BLEND_CLASS::MASKED, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::MESH_MASKED },
			{ "decal", EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT, "none",
				EFFECT_ELEMENT_KIND::DECAL,
				EFFECT_GENERIC_AUTHORING_FAMILY::DECAL_TRANSLUCENT },
			{ "sprite", EFFECT_SOURCE_BLEND_CLASS::MASKED, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::SPRITE_MASKED },
			{ "mesh", EFFECT_SOURCE_BLEND_CLASS::MASKED,
				"psuvim_linear_blend_random_flip_square",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::MESH_MASKED_SUBUV },
			{ "mesh", EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT,
				"psuvim_linear_blend", EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::MESH_TRANSLUCENT_SUBUV },
			{ "decal", EFFECT_SOURCE_BLEND_CLASS::ADDITIVE, "none",
				EFFECT_ELEMENT_KIND::DECAL,
				EFFECT_GENERIC_AUTHORING_FAMILY::DECAL_ADDITIVE },
			{ "mesh", EFFECT_SOURCE_BLEND_CLASS::UNKNOWN, "none",
				EFFECT_ELEMENT_KIND::PARTICLE,
				EFFECT_GENERIC_AUTHORING_FAMILY::MESH_UNKNOWN }
		}};
		bool_t bFamilyTableExact =
			FamilyCases.size() == static_cast<size_t>(
				EFFECT_GENERIC_AUTHORING_FAMILY::END);
		bool_t bRenderStateIndependent = true;
		std::set<EFFECT_GENERIC_AUTHORING_FAMILY> ObservedFamilies;
		for (const FAMILY_CASE& FamilyCase : FamilyCases)
		{
			EFFECT_ELEMENT_DESC Probe;
			Probe.eKind = FamilyCase.eKind;
			Probe.SourceRecipe.strRendererShape = FamilyCase.pShape;
			Probe.Material.SourceMaterial.eSourceBlendClass = FamilyCase.eBlend;
			Probe.Material.SourceMaterial.strSubUVMode = FamilyCase.pSubUV;
			Probe.Material.eRenderProfile =
				FamilyCase.eBlend == EFFECT_SOURCE_BLEND_CLASS::UNKNOWN ?
				EFFECT_RENDER_PROFILE::OPAQUE_BACK_DEPTH_WRITE :
				EFFECT_RENDER_PROFILE::ALPHA_TWO_SIDED_DEPTH_READ;
			const EFFECT_GENERIC_AUTHORING_FAMILY eResolved =
				Resolve_EffectGenericAuthoringFamily(Probe);
			bFamilyTableExact = bFamilyTableExact &&
				eResolved == FamilyCase.eExpected &&
				std::string_view(Get_EffectGenericAuthoringFamilyLabel(eResolved)) !=
					"Unknown";
			ObservedFamilies.insert(eResolved);

			/* Family is compiler-derived. Changing the independent cull/render
			   state must not behave like a second authoring-family selector. */
			Probe.Material.eRenderProfile =
				FamilyCase.eBlend == EFFECT_SOURCE_BLEND_CLASS::UNKNOWN ?
				EFFECT_RENDER_PROFILE::END :
				EFFECT_RENDER_PROFILE::ALPHA_ONE_SIDED_DEPTH_READ;
			bRenderStateIndependent = bRenderStateIndependent &&
				Resolve_EffectGenericAuthoringFamily(Probe) ==
					FamilyCase.eExpected;
		}
		runner.Require(bFamilyTableExact &&
			ObservedFamilies.size() == FamilyCases.size(),
			"G3 Internal Resolver Covers Exactly Thirteen Compiler-Derived Families");
		runner.Require(bRenderStateIndependent,
			"G3 Internal Family Has No One-Sided Or Two-Sided Selector Axis");

		SCOPED_ENVIRONMENT_VARIABLE RuntimeResourceRoot(
			L"LOSTARK_RESOURCE_ROOT");
		std::filesystem::path RuntimeResourceRootPath;
		if (RuntimeResourceRoot.Was_Defined() &&
			!RuntimeResourceRoot.Get_OriginalValue().empty())
		{
			RuntimeResourceRootPath =
				RuntimeResourceRoot.Get_OriginalValue();
		}
		else
		{
			RuntimeResourceRootPath =
				CProjectDataRoot::Get().parent_path() / L"Client" / L"Bin" /
				L"Resources";
		}
		std::vector<std::string> TextureIds;
		std::vector<std::string> ModelIds;
		std::error_code AssetError;
		const bool_t bNeedsResourceRootOverride =
			!RuntimeResourceRoot.Was_Defined() ||
			RuntimeResourceRoot.Get_OriginalValue().empty();
		if (std::filesystem::is_directory(RuntimeResourceRootPath, AssetError) &&
			!AssetError && (!bNeedsResourceRootOverride ||
				RuntimeResourceRoot.Set(RuntimeResourceRootPath.c_str())))
		{
			const std::filesystem::path EffectRoot =
				RuntimeResourceRootPath / L"Effect";
			for (std::filesystem::recursive_directory_iterator Iterator(
					 EffectRoot,
					 std::filesystem::directory_options::skip_permission_denied,
					 AssetError), End;
				 !AssetError && Iterator != End &&
					(TextureIds.size() < 3u || ModelIds.empty());
				 Iterator.increment(AssetError))
			{
				if (!Iterator->is_regular_file(AssetError) || AssetError)
				{
					AssetError.clear();
					continue;
				}
				const std::filesystem::path Relative =
					std::filesystem::relative(Iterator->path(),
						RuntimeResourceRootPath, AssetError);
				if (AssetError)
					break;
				const std::string AssetId = Relative.generic_string();
				EFFECT_RESOURCE_FILE_KIND eKind =
					EFFECT_RESOURCE_FILE_KIND::END;
				if (!CEffectDocumentCodec::Is_SafeResourceAssetId(
						AssetId, &eKind))
				{
					continue;
				}
				if (eKind == EFFECT_RESOURCE_FILE_KIND::TEXTURE &&
					!Is_UnsafeEffectBaseTextureAssetId(AssetId) &&
					TextureIds.size() < 3u)
				{
					TextureIds.push_back(AssetId);
				}
				else if (eKind == EFFECT_RESOURCE_FILE_KIND::MODEL &&
					ModelIds.empty())
				{
					ModelIds.push_back(AssetId);
				}
			}
		}
		const bool_t bAssetsReady = !AssetError &&
			TextureIds.size() == 3u && ModelIds.size() == 1u;
		runner.Require(bAssetsReady,
			"G3 Override Fixture Resolves Three Physical DDS And One WModel Asset");
		if (!bAssetsReady)
		{
			std::cout << "[DETAIL] G3 resource root: "
				<< RuntimeResourceRootPath.string() << " error="
				<< AssetError.message() << '\n';
			return;
		}

		constexpr const char_t* TargetElementId = "g3.fixture.target";
		constexpr const char_t* SupportElementId = "g3.fixture.support";
		constexpr const char_t* LaneId = "g3.lane";
		constexpr const char_t* NamedTexture = "g3.named.texture";
		constexpr const char_t* SourceOnlyScalar = "g3.source.only.scalar";
		constexpr const char_t* ExecutionOnlyScalar =
			"g3.execution.only.scalar";
		constexpr const char_t* MirroredScalar = "g3.mirrored.scalar";
		constexpr const char_t* SourceOnlyColor = "g3.source.only.color";
		constexpr const char_t* ExecutionOnlyColor =
			"g3.execution.only.color";
		constexpr const char_t* MirroredColor = "g3.mirrored.color";
		const std::string LaneSlotId =
			Build_EffectMaterialExecutionLaneStableSlotId(LaneId);
		const std::string NamedTextureSlotId =
			Build_EffectSourceMaterialTextureStableSlotId(NamedTexture);

		struct COMPILER_VALUES final
		{
			std::string strTextureAssetId;
			std::string strProfileId;
			f32_t fSourceOnlyScalar = 0.f;
			f32_t fExecutionOnlyScalar = 0.f;
			f32_t fMirroredScalar = 0.f;
			float4_t vSourceOnlyColor{};
			float4_t vExecutionOnlyColor{};
			float4_t vMirroredColor{};
		};
		const COMPILER_VALUES CompilerV1Values = {
			TextureIds[0u], "g3.compiler.v1", 1.f, 2.f, 3.f,
			{ 0.1f, 0.2f, 0.3f, 0.4f },
			{ 0.2f, 0.3f, 0.4f, 0.5f },
			{ 0.3f, 0.4f, 0.5f, 0.6f }
		};
		const COMPILER_VALUES CompilerV2Values = {
			TextureIds[2u], "g3.compiler.v2", 11.f, 12.f, 13.f,
			{ 0.11f, 0.21f, 0.31f, 0.41f },
			{ 0.21f, 0.31f, 0.41f, 0.51f },
			{ 0.31f, 0.41f, 0.51f, 0.61f }
		};
		const COMPILER_VALUES ArtistValues = {
			TextureIds[1u], "g3.artist.never.compiler", 101.f, 102.f, 103.f,
			{ 0.71f, 0.72f, 0.73f, 0.74f },
			{ 0.61f, 0.62f, 0.63f, 0.64f },
			{ 0.51f, 0.52f, 0.53f, 0.54f }
		};
		const auto SameFloat4 = [](const float4_t& Left,
			const float4_t& Right)
		{
			return Left.x == Right.x && Left.y == Right.y &&
				Left.z == Right.z && Left.w == Right.w;
		};

		const auto MakeCompilerDocument = [&](const COMPILER_VALUES& Values)
		{
			EFFECT_DOCUMENT_DESC Document;
			Document.strEffectAssetId = "effect.g3.authoring.fixture";
			Document.strDisplayName = "G3 authoring ownership fixture";

			EFFECT_ELEMENT_DESC Support;
			Support.strElementId = SupportElementId;
			Support.strDisplayName = "G3 support";
			Support.strGroupId = "manual.g3";
			Support.eKind = EFFECT_ELEMENT_KIND::DECAL;
			Support.ResourceBindings.push_back(
				{ "base", Values.strTextureAssetId });
			Document.Elements.push_back(std::move(Support));

			EFFECT_ELEMENT_DESC Target;
			Target.strElementId = TargetElementId;
			Target.strDisplayName = "Compiler G3 target";
			Target.strGroupId = "compiler.g3";
			Target.eKind = EFFECT_ELEMENT_KIND::DECAL;
			Target.ResourceBindings.push_back(
				{ "base", Values.strTextureAssetId });
			Target.Material.eRenderProfile =
				EFFECT_RENDER_PROFILE::ALPHA_TWO_SIDED_DEPTH_READ;
			Target.Material.SourceMaterial.bEnabled = true;
			Target.Material.SourceMaterial.strProfileId = Values.strProfileId;
			Target.Material.SourceMaterial.strRuntimeShaderProfileId =
				"effect.ue3.reconstructed-standard.v1";
			Target.Material.SourceMaterial.strParentMaterialPath =
				"Material'/Game/G3/Compiler'";
			Target.Material.SourceMaterial.eStatus =
				EFFECT_SOURCE_MATERIAL_STATUS::RECONSTRUCTED_PROFILE;
			Target.Material.SourceMaterial.eSourceBlendClass =
				EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT;
			Target.Material.SourceMaterial.strSubUVMode = "none";
			EFFECT_NAMED_TEXTURE_DESC Texture;
			Texture.strName = NamedTexture;
			Texture.strGroup = "g3";
			Texture.strSourceObjectPath =
				"Texture2D'/Game/G3/CompilerTexture'";
			Texture.strAssetId = Values.strTextureAssetId;
			Texture.eColorSpace = EFFECT_TEXTURE_COLOR_SPACE::SRGB;
			Texture.strSamplingEvidence = "compiler_capture";
			Target.Material.SourceMaterial.Textures.push_back(std::move(Texture));
			Target.Material.SourceMaterial.Scalars = {
				{ SourceOnlyScalar, "g3", Values.fSourceOnlyScalar },
				{ MirroredScalar, "g3", Values.fMirroredScalar }
			};
			Target.Material.SourceMaterial.Vectors = {
				{ SourceOnlyColor, "g3", Values.vSourceOnlyColor },
				{ MirroredColor, "g3", Values.vMirroredColor }
			};

			EFFECT_MATERIAL_EXECUTION_DESC& Execution =
				Target.Material.Execution;
			Execution.bEnabled = true;
			Execution.eBackend =
				EFFECT_MATERIAL_EXECUTION_BACKEND::ARTIST_VISUAL_V4;
			Execution.iOpcode = 1u;
			Execution.strRasterizerState = "g3.rasterizer";
			Execution.strDepthStencilState = "g3.depth";
			Execution.strBlendState = "g3.blend";
			Execution.iTextureLaneCount = 1u;
			Execution.iTextureMask = 1u;
			EFFECT_MATERIAL_TEXTURE_LANE_DESC Lane;
			Lane.strLaneId = LaneId;
			Lane.strRole = "base";
			Lane.strAssetId = Values.strTextureAssetId;
			Lane.iTextureRegister = 0u;
			Lane.iSamplerRegister = 5u;
			Lane.eColorSpace = EFFECT_TEXTURE_COLOR_SPACE::SRGB;
			Execution.TextureLanes.push_back(std::move(Lane));
			Execution.iScalarCount = 2u;
			Execution.Scalars = {
				{ ExecutionOnlyScalar, 0u, Values.fExecutionOnlyScalar },
				{ MirroredScalar, 1u, Values.fMirroredScalar }
			};
			Execution.iVectorCount = 2u;
			Execution.Vectors = {
				{ ExecutionOnlyColor, 0u, Values.vExecutionOnlyColor },
				{ MirroredColor, 1u, Values.vMirroredColor }
			};
			Execution.ArtistParameters = {
				{ MirroredColor, 0u, Values.vMirroredColor }
			};
			Execution.Colors = {
				{ MirroredColor, 0u, Values.vMirroredColor }
			};
			Target.SourceRecipe.bEnabled = true;
			Target.SourceRecipe.strRendererShape = "decal";
			Target.SourceRecipe.fEmitterDurationSeconds = 1.f;
			Target.Detail.Transform.vPosition = { 1.f, 2.f, 3.f };
			Document.Elements.push_back(std::move(Target));
			return Document;
		};
		const auto FindTarget = [&](EFFECT_DOCUMENT_DESC& Document)
			-> EFFECT_ELEMENT_DESC*
		{
			const auto Iterator = std::find_if(Document.Elements.begin(),
				Document.Elements.end(), [&](const EFFECT_ELEMENT_DESC& Element)
				{
					return Element.strElementId == TargetElementId;
				});
			return Iterator == Document.Elements.end() ? nullptr : &*Iterator;
		};
		const auto FindResourceBinding = [](EFFECT_ELEMENT_DESC& Element,
			const std::string_view SlotId) -> EFFECT_RESOURCE_BINDING_DESC*
		{
			const auto Iterator = std::find_if(Element.ResourceBindings.begin(),
				Element.ResourceBindings.end(), [SlotId](const auto& Binding)
				{
					return Binding.strSlotId == SlotId;
				});
			return Iterator == Element.ResourceBindings.end() ?
				nullptr : &*Iterator;
		};
		const auto AllScalarTargetsEqual = [](const EFFECT_ELEMENT_DESC& Element,
			const std::string_view Name, const f32_t Value,
			const size_t ExpectedCount)
		{
			size_t Count = 0u;
			bool_t bEqual = true;
			for (const EFFECT_NAMED_FLOAT_DESC& Scalar :
				Element.Material.SourceMaterial.Scalars)
			{
				if (Scalar.strName == Name)
				{
					++Count;
					bEqual = bEqual && Scalar.fValue == Value;
				}
			}
			for (const EFFECT_MATERIAL_SCALAR_PARAMETER_DESC& Scalar :
				Element.Material.Execution.Scalars)
			{
				if (Scalar.strName == Name)
				{
					++Count;
					bEqual = bEqual && Scalar.fValue == Value;
				}
			}
			return bEqual && Count == ExpectedCount;
		};
		const auto AllColorTargetsEqual = [&SameFloat4](
			const EFFECT_ELEMENT_DESC& Element, const std::string_view Name,
			const float4_t& Value, const size_t ExpectedCount)
		{
			size_t Count = 0u;
			bool_t bEqual = true;
			const auto CountRows = [&](const auto& Rows)
			{
				for (const auto& Row : Rows)
				{
					if (Row.strName == Name)
					{
						++Count;
						bEqual = bEqual && SameFloat4(Row.vValue, Value);
					}
				}
			};
			CountRows(Element.Material.SourceMaterial.Vectors);
			CountRows(Element.Material.Execution.Vectors);
			CountRows(Element.Material.Execution.ArtistParameters);
			CountRows(Element.Material.Execution.Colors);
			return bEqual && Count == ExpectedCount;
		};
		const auto HasResourceOverride = [](const EFFECT_ELEMENT_DESC& Element,
			const std::string_view SlotId, const std::string_view ArtistAssetId,
			const std::string_view CompilerAssetId)
		{
			return std::any_of(Element.AuthoringOverrides.ResourceBindings.begin(),
				Element.AuthoringOverrides.ResourceBindings.end(),
				[&](const EFFECT_AUTHORING_RESOURCE_OVERRIDE_DESC& Override)
				{
					return Override.strSlotId == SlotId &&
						Override.strAssetId == ArtistAssetId &&
						Override.strCompilerAssetId == CompilerAssetId;
				});
		};
		const auto HasScalarOverride = [](const EFFECT_ELEMENT_DESC& Element,
			const std::string_view Name, const f32_t ArtistValue,
			const f32_t CompilerValue)
		{
			return std::any_of(Element.AuthoringOverrides.Scalars.begin(),
				Element.AuthoringOverrides.Scalars.end(),
				[&](const EFFECT_AUTHORING_SCALAR_OVERRIDE_DESC& Override)
				{
					return Override.strName == Name &&
						Override.fValue == ArtistValue &&
						Override.fCompilerValue == CompilerValue;
				});
		};
		const auto HasColorOverride = [&SameFloat4](
			const EFFECT_ELEMENT_DESC& Element, const std::string_view Name,
			const float4_t& ArtistValue, const float4_t& CompilerValue)
		{
			return std::any_of(Element.AuthoringOverrides.Colors.begin(),
				Element.AuthoringOverrides.Colors.end(),
				[&](const EFFECT_AUTHORING_COLOR_OVERRIDE_DESC& Override)
				{
					return Override.strName == Name &&
						SameFloat4(Override.vValue, ArtistValue) &&
						SameFloat4(Override.vCompilerValue, CompilerValue);
				});
		};

		std::string status;
		EFFECT_DOCUMENT_DESC CompilerV1 =
			MakeCompilerDocument(CompilerV1Values);
		const bool_t bCompilerFixtureValid =
			CEffectDocumentCodec::Validate(CompilerV1, status);
		runner.Require(bCompilerFixtureValid,
			"G3 Compiler-Owned Fixture Is A Canonical Ordinary V13 Document");
		if (!bCompilerFixtureValid)
		{
			std::cout << "[DETAIL] G3 compiler fixture: " << status << '\n';
			return;
		}

		EFFECT_DOCUMENT_DESC Authored = CompilerV1;
		EFFECT_ELEMENT_DESC* pAuthored = FindTarget(Authored);
		if (nullptr == pAuthored)
		{
			runner.Require(false, "G3 Authored Fixture Keeps Its Stable Target");
			return;
		}
		pAuthored->strDisplayName = "Artist-owned G3 target";
		pAuthored->strGroupId = "manual.g3.artist";
		pAuthored->bVisible = false;
		pAuthored->Detail.Transform.vPosition = { 7.f, 8.f, 9.f };
		pAuthored->ActionCueAttachment.bEnabled = true;
		pAuthored->ActionCueAttachment.strSourceAnchorSlotId = "source.root";
		pAuthored->ActionCueAttachment.strRuntimeAnchorSlotId = "runtime.root";
		pAuthored->TransformInheritance.bEnabled = true;
		pAuthored->TransformInheritance.strMasterElementId = SupportElementId;
		const auto SupportIterator = std::find_if(Authored.Elements.begin(),
			Authored.Elements.end(), [&](const EFFECT_ELEMENT_DESC& Element)
			{
				return Element.strElementId == SupportElementId;
			});
		if (SupportIterator != Authored.Elements.end())
		{
			SupportIterator->strGroupId = pAuthored->strGroupId;
			SupportIterator->ActionCueAttachment =
				pAuthored->ActionCueAttachment;
		}

		bool_t bSetSucceeded = true;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringResourceOverride(
			*pAuthored, "base", ArtistValues.strTextureAssetId, status) &&
			bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringResourceOverride(
			*pAuthored, LaneSlotId, ArtistValues.strTextureAssetId, status) &&
			bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringResourceOverride(
			*pAuthored, NamedTextureSlotId, ArtistValues.strTextureAssetId,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringScalarOverride(
			*pAuthored, SourceOnlyScalar, ArtistValues.fSourceOnlyScalar,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringScalarOverride(
			*pAuthored, ExecutionOnlyScalar, ArtistValues.fExecutionOnlyScalar,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringColorOverride(
			*pAuthored, SourceOnlyColor, ArtistValues.vSourceOnlyColor,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringColorOverride(
			*pAuthored, ExecutionOnlyColor, ArtistValues.vExecutionOnlyColor,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringScalarOverride(
			*pAuthored, MirroredScalar, ArtistValues.fMirroredScalar,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringColorOverride(
			*pAuthored, MirroredColor, ArtistValues.vMirroredColor,
			status) && bSetSucceeded;
		runner.Require(bSetSucceeded &&
			AllScalarTargetsEqual(*pAuthored, SourceOnlyScalar,
				ArtistValues.fSourceOnlyScalar, 1u) &&
			AllScalarTargetsEqual(*pAuthored, ExecutionOnlyScalar,
				ArtistValues.fExecutionOnlyScalar, 1u) &&
			AllScalarTargetsEqual(*pAuthored, MirroredScalar,
				ArtistValues.fMirroredScalar, 2u) &&
			AllColorTargetsEqual(*pAuthored, SourceOnlyColor,
				ArtistValues.vSourceOnlyColor, 1u) &&
			AllColorTargetsEqual(*pAuthored, ExecutionOnlyColor,
				ArtistValues.vExecutionOnlyColor, 1u) &&
			AllColorTargetsEqual(*pAuthored, MirroredColor,
				ArtistValues.vMirroredColor, 4u),
			"G3 Set Applies Resource Source-Only Execution-Only And Mirrored Parameter Overrides");
		if (!bSetSucceeded)
			std::cout << "[DETAIL] G3 set override: " << status << '\n';

		const bool_t bMirroredReset =
			CEffectDocumentCodec::Reset_AuthoringScalarOverride(
				*pAuthored, MirroredScalar, status) &&
			CEffectDocumentCodec::Reset_AuthoringColorOverride(
				*pAuthored, MirroredColor, status);
		runner.Require(bMirroredReset &&
			AllScalarTargetsEqual(*pAuthored, MirroredScalar,
				CompilerV1Values.fMirroredScalar, 2u) &&
			AllColorTargetsEqual(*pAuthored, MirroredColor,
				CompilerV1Values.vMirroredColor, 4u) &&
			!HasScalarOverride(*pAuthored, MirroredScalar,
				ArtistValues.fMirroredScalar,
				CompilerV1Values.fMirroredScalar) &&
			!HasColorOverride(*pAuthored, MirroredColor,
				ArtistValues.vMirroredColor,
				CompilerV1Values.vMirroredColor),
			"G3 Reset Restores Every Mirrored Effective Target And Retires Its Delta");
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringScalarOverride(
			*pAuthored, MirroredScalar, ArtistValues.fMirroredScalar,
			status) && bSetSucceeded;
		bSetSucceeded = CEffectDocumentCodec::Set_AuthoringColorOverride(
			*pAuthored, MirroredColor, ArtistValues.vMirroredColor,
			status) && bSetSucceeded;

		const EFFECT_AUTHORING_FIDELITY eExactFidelityBefore =
			Get_EffectAuthoringFidelity(pAuthored->Material.Execution);
		const bool_t bExecutionAdmissionBefore =
			Is_EffectAuthoringExecutionTarget(pAuthored->Material.Execution);
		const std::string AuthoredCanonical =
			CEffectDocumentCodec::Serialize(Authored);
		EFFECT_DOCUMENT_DESC RoundTrip;
		const bool_t bRoundTrip = bSetSucceeded &&
			SupportIterator != Authored.Elements.end() &&
			CEffectDocumentCodec::Parse(AuthoredCanonical, RoundTrip, status) &&
			CEffectDocumentCodec::Serialize(RoundTrip) == AuthoredCanonical;
		EFFECT_ELEMENT_DESC* pRoundTrip = bRoundTrip ?
			FindTarget(RoundTrip) : nullptr;
		runner.Require(nullptr != pRoundTrip &&
			pRoundTrip->AuthoringOverrides.ResourceBindings.size() == 3u &&
			pRoundTrip->AuthoringOverrides.Scalars.size() == 3u &&
			pRoundTrip->AuthoringOverrides.Colors.size() == 3u,
			"G3 Resource Scalar And Color Overrides Serialize And Parse Canonically");
		if (nullptr == pRoundTrip)
		{
			std::cout << "[DETAIL] G3 canonical round trip: " << status << '\n';
			return;
		}

		const auto RejectsSetterWithoutMutation = [&](
			const EFFECT_DOCUMENT_DESC& Input, const auto& Mutation)
		{
			EFFECT_DOCUMENT_DESC Probe = Input;
			EFFECT_ELEMENT_DESC* pProbe = FindTarget(Probe);
			if (nullptr == pProbe)
				return false;
			const std::string Before = CEffectDocumentCodec::Serialize(Probe);
			std::string ExpectedError;
			return !Mutation(*pProbe, ExpectedError) && !ExpectedError.empty() &&
				CEffectDocumentCodec::Serialize(Probe) == Before;
		};
		const bool_t bInvalidSetterRollback =
			RejectsSetterWithoutMutation(RoundTrip,
				[](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringResourceOverride(
						Element, "", "../unsafe.dds", Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringResourceOverride(
						Element, "base", "../unsafe.dds", Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringResourceOverride(
						Element, "base", ModelIds.front(), Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringResourceOverride(
						Element, "missing.slot", "Effect/missing.dds", Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringScalarOverride(
						Element, SourceOnlyColor, 4.f, Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringColorOverride(
						Element, SourceOnlyScalar, {}, Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringScalarOverride(
						Element, "missing.scalar", 4.f, Error);
				}) &&
			RejectsSetterWithoutMutation(RoundTrip,
				[](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringColorOverride(
						Element, "missing.color", {}, Error);
				});
		runner.Require(bInvalidSetterRollback,
			"G3 Set Rejects Invalid ID Unsafe Path Wrong Kind Type And Unknown Target Transactionally");

		EFFECT_DOCUMENT_DESC Duplicate = RoundTrip;
		EFFECT_ELEMENT_DESC* pDuplicate = FindTarget(Duplicate);
		if (nullptr != pDuplicate)
		{
			pDuplicate->AuthoringOverrides.ResourceBindings.push_back(
				pDuplicate->AuthoringOverrides.ResourceBindings.front());
		}
		EFFECT_DOCUMENT_DESC EffectiveMismatch = RoundTrip;
		EFFECT_ELEMENT_DESC* pMismatch = FindTarget(EffectiveMismatch);
		EFFECT_RESOURCE_BINDING_DESC* pMismatchBase = nullptr == pMismatch ?
			nullptr : FindResourceBinding(*pMismatch, "base");
		if (nullptr != pMismatchBase)
			pMismatchBase->strAssetId = CompilerV1Values.strTextureAssetId;
		EFFECT_DOCUMENT_DESC RejectedParse;
		const bool_t bDuplicateAndEffectiveMismatchRejected =
			nullptr != pDuplicate && nullptr != pMismatchBase &&
			!CEffectDocumentCodec::Parse(
				CEffectDocumentCodec::Serialize(Duplicate), RejectedParse, status) &&
			!CEffectDocumentCodec::Parse(
				CEffectDocumentCodec::Serialize(EffectiveMismatch),
				RejectedParse, status) &&
			RejectsSetterWithoutMutation(Duplicate,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringResourceOverride(
						Element, "base", ArtistValues.strTextureAssetId, Error);
				}) &&
			RejectsSetterWithoutMutation(EffectiveMismatch,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringResourceOverride(
						Element, "base", ArtistValues.strTextureAssetId, Error);
				});
		runner.Require(bDuplicateAndEffectiveMismatchRejected,
			"G3 Duplicate And Effective-Mismatch Fixtures Fail Closed Without Setter Commit");

		EFFECT_DOCUMENT_DESC MirrorScalarMismatch = CompilerV1;
		EFFECT_ELEMENT_DESC* pMirrorScalarMismatch =
			FindTarget(MirrorScalarMismatch);
		if (nullptr != pMirrorScalarMismatch)
		{
			pMirrorScalarMismatch->Material.Execution.Scalars.back().fValue += 1.f;
		}
		EFFECT_DOCUMENT_DESC MirrorColorMismatch = CompilerV1;
		EFFECT_ELEMENT_DESC* pMirrorColorMismatch =
			FindTarget(MirrorColorMismatch);
		if (nullptr != pMirrorColorMismatch)
		{
			pMirrorColorMismatch->Material.Execution.Colors.front().vValue.x +=
				0.01f;
		}
		runner.Require(nullptr != pMirrorScalarMismatch &&
			nullptr != pMirrorColorMismatch &&
			RejectsSetterWithoutMutation(MirrorScalarMismatch,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringScalarOverride(
						Element, MirroredScalar,
						ArtistValues.fMirroredScalar, Error);
				}) &&
			RejectsSetterWithoutMutation(MirrorColorMismatch,
				[&](EFFECT_ELEMENT_DESC& Element, std::string& Error)
				{
					return CEffectDocumentCodec::Set_AuthoringColorOverride(
						Element, MirroredColor,
						ArtistValues.vMirroredColor, Error);
				}),
			"G3 Mirrored Source And Execution Targets Require One Compiler Value");

		EFFECT_DOCUMENT_DESC Approximate = CompilerV1;
		EFFECT_ELEMENT_DESC* pApproximate = FindTarget(Approximate);
		bool_t bApproximateOverride = false;
		if (nullptr != pApproximate)
		{
			pApproximate->Material.Execution = {};
			pApproximate->Material.Execution.bFailClosed = true;
			pApproximate->Material.Execution.bAuthoringApproximate = true;
			bApproximateOverride =
				CEffectDocumentCodec::Set_AuthoringResourceOverride(
					*pApproximate, "base", ArtistValues.strTextureAssetId,
					status) &&
				CEffectDocumentCodec::Set_AuthoringScalarOverride(
					*pApproximate, SourceOnlyScalar,
					ArtistValues.fSourceOnlyScalar, status) &&
				CEffectDocumentCodec::Validate(Approximate, status);
		}
		runner.Require(bApproximateOverride && nullptr != pApproximate &&
			Get_EffectAuthoringFidelity(pApproximate->Material.Execution) ==
				EFFECT_AUTHORING_FIDELITY::APPROXIMATE &&
			Is_EffectAuthoringExecutionTarget(
				pApproximate->Material.Execution) &&
			!pApproximate->Material.Execution.bEnabled &&
			pApproximate->Material.Execution.bFailClosed &&
			pApproximate->Material.Execution.bAuthoringApproximate,
			"G3 Override Cannot Launder Approximate Fidelity Or Product Admission");

		EFFECT_DOCUMENT_DESC CompilerV2 =
			MakeCompilerDocument(CompilerV2Values);
		EFFECT_DOCUMENT_DESC ExistingForReimport = RoundTrip;
		EFFECT_ELEMENT_DESC* pExistingForReimport =
			FindTarget(ExistingForReimport);
		if (nullptr != pExistingForReimport)
		{
			/* A valid but artist-forged compiler profile must be replaced by the
			   next compiler stage; only the override values are artist-owned. */
			pExistingForReimport->Material.SourceMaterial.strProfileId =
				"g3.artist.forged";
			pExistingForReimport->Material.SourceMaterial.strParentMaterialPath =
				"Material'/Game/G3/ArtistForged'";
			pExistingForReimport->Material.SourceMaterial.eStatus =
				EFFECT_SOURCE_MATERIAL_STATUS::SOURCE_EXACT;
			pExistingForReimport->Material.SourceMaterial.eSourceBlendClass =
				EFFECT_SOURCE_BLEND_CLASS::ADDITIVE;
		}
		EFFECT_GENERIC_AUTHORED_ELEMENT_REIMPORT_REQUEST Request;
		Request.strElementId = TargetElementId;
		EFFECT_DOCUMENT_DESC Reimported;
		EFFECT_GENERIC_AUTHORED_REIMPORT_REPORT ReimportReport;
		const std::string CompilerV2Before =
			CEffectDocumentCodec::Serialize(CompilerV2);
		const std::string ExistingBefore =
			CEffectDocumentCodec::Serialize(ExistingForReimport);
		const bool_t bReimported = nullptr != pExistingForReimport &&
			CEffectDocumentCodec::Build_GenericAuthoredElementReimportStage(
				CompilerV2, ExistingForReimport, Request, Reimported, status,
				&ReimportReport) && ReimportReport.DroppedOverrides.empty() &&
			CEffectDocumentCodec::Serialize(CompilerV2) == CompilerV2Before &&
			CEffectDocumentCodec::Serialize(ExistingForReimport) == ExistingBefore;
		EFFECT_ELEMENT_DESC* pReimported = bReimported ?
			FindTarget(Reimported) : nullptr;
		const auto ResourcesEqualArtist = [&](const EFFECT_ELEMENT_DESC& Element)
		{
			const auto Base = std::find_if(Element.ResourceBindings.begin(),
				Element.ResourceBindings.end(), [](const auto& Binding)
				{
					return Binding.strSlotId == "base";
				});
			const auto Lane = std::find_if(
				Element.Material.Execution.TextureLanes.begin(),
				Element.Material.Execution.TextureLanes.end(),
				[&](const auto& Row) { return Row.strLaneId == LaneId; });
			const auto Texture = std::find_if(
				Element.Material.SourceMaterial.Textures.begin(),
				Element.Material.SourceMaterial.Textures.end(),
				[&](const auto& Row) { return Row.strName == NamedTexture; });
			return Base != Element.ResourceBindings.end() &&
				Lane != Element.Material.Execution.TextureLanes.end() &&
				Texture != Element.Material.SourceMaterial.Textures.end() &&
				Base->strAssetId == ArtistValues.strTextureAssetId &&
				Lane->strAssetId == ArtistValues.strTextureAssetId &&
				Texture->strAssetId == ArtistValues.strTextureAssetId;
		};
		const bool_t bReimportPreservedAndRebased = nullptr != pReimported &&
			pReimported->strDisplayName == "Artist-owned G3 target" &&
			pReimported->strGroupId == "manual.g3.artist" &&
			!pReimported->bVisible &&
			pReimported->Detail.Transform.vPosition.x == 7.f &&
			pReimported->Detail.Transform.vPosition.y == 8.f &&
			pReimported->Detail.Transform.vPosition.z == 9.f &&
			pReimported->ActionCueAttachment.bEnabled &&
			pReimported->TransformInheritance.bEnabled &&
			pReimported->TransformInheritance.strMasterElementId ==
				SupportElementId &&
			pReimported->Material.SourceMaterial.strProfileId ==
				CompilerV2Values.strProfileId &&
			pReimported->Material.SourceMaterial.strParentMaterialPath ==
				"Material'/Game/G3/Compiler'" &&
			pReimported->Material.SourceMaterial.eStatus ==
				EFFECT_SOURCE_MATERIAL_STATUS::RECONSTRUCTED_PROFILE &&
			pReimported->Material.SourceMaterial.eSourceBlendClass ==
				EFFECT_SOURCE_BLEND_CLASS::TRANSLUCENT &&
			ResourcesEqualArtist(*pReimported) &&
			AllScalarTargetsEqual(*pReimported, SourceOnlyScalar,
				ArtistValues.fSourceOnlyScalar, 1u) &&
			AllScalarTargetsEqual(*pReimported, ExecutionOnlyScalar,
				ArtistValues.fExecutionOnlyScalar, 1u) &&
			AllScalarTargetsEqual(*pReimported, MirroredScalar,
				ArtistValues.fMirroredScalar, 2u) &&
			AllColorTargetsEqual(*pReimported, SourceOnlyColor,
				ArtistValues.vSourceOnlyColor, 1u) &&
			AllColorTargetsEqual(*pReimported, ExecutionOnlyColor,
				ArtistValues.vExecutionOnlyColor, 1u) &&
			AllColorTargetsEqual(*pReimported, MirroredColor,
				ArtistValues.vMirroredColor, 4u) &&
			HasResourceOverride(*pReimported, "base",
				ArtistValues.strTextureAssetId,
				CompilerV2Values.strTextureAssetId) &&
			HasResourceOverride(*pReimported, LaneSlotId,
				ArtistValues.strTextureAssetId,
				CompilerV2Values.strTextureAssetId) &&
			HasResourceOverride(*pReimported, NamedTextureSlotId,
				ArtistValues.strTextureAssetId,
				CompilerV2Values.strTextureAssetId) &&
			HasScalarOverride(*pReimported, SourceOnlyScalar,
				ArtistValues.fSourceOnlyScalar,
				CompilerV2Values.fSourceOnlyScalar) &&
			HasScalarOverride(*pReimported, ExecutionOnlyScalar,
				ArtistValues.fExecutionOnlyScalar,
				CompilerV2Values.fExecutionOnlyScalar) &&
			HasScalarOverride(*pReimported, MirroredScalar,
				ArtistValues.fMirroredScalar,
				CompilerV2Values.fMirroredScalar) &&
			HasColorOverride(*pReimported, SourceOnlyColor,
				ArtistValues.vSourceOnlyColor,
				CompilerV2Values.vSourceOnlyColor) &&
			HasColorOverride(*pReimported, ExecutionOnlyColor,
				ArtistValues.vExecutionOnlyColor,
				CompilerV2Values.vExecutionOnlyColor) &&
			HasColorOverride(*pReimported, MirroredColor,
				ArtistValues.vMirroredColor,
				CompilerV2Values.vMirroredColor) &&
			Get_EffectAuthoringFidelity(pReimported->Material.Execution) ==
				eExactFidelityBefore &&
			Is_EffectAuthoringExecutionTarget(
				pReimported->Material.Execution) == bExecutionAdmissionBefore;
		runner.Require(bReimported && bReimportPreservedAndRebased,
			"G3 Reimport Preserves Artist Fields And Overrides While Rebasing Compiler Baselines");
		if (!bReimported)
			std::cout << "[DETAIL] G3 reimport: " << status << '\n';
		if (nullptr == pReimported)
			return;

		EFFECT_DOCUMENT_DESC NoOpCompiler =
			MakeCompilerDocument(ArtistValues);
		EFFECT_ELEMENT_DESC* pNoOpCompiler = FindTarget(NoOpCompiler);
		if (nullptr != pNoOpCompiler)
			pNoOpCompiler->Material.SourceMaterial.strProfileId = "g3.compiler.v3";
		EFFECT_DOCUMENT_DESC NoOpRetired;
		EFFECT_GENERIC_AUTHORED_REIMPORT_REPORT NoOpReport;
		const bool_t bNoOpRetired = nullptr != pNoOpCompiler &&
			CEffectDocumentCodec::Build_GenericAuthoredElementReimportStage(
				NoOpCompiler, Reimported, Request, NoOpRetired, status,
				&NoOpReport);
		EFFECT_ELEMENT_DESC* pNoOpRetired = bNoOpRetired ?
			FindTarget(NoOpRetired) : nullptr;
		runner.Require(nullptr != pNoOpRetired &&
			pNoOpRetired->AuthoringOverrides.Is_Empty() &&
			NoOpReport.DroppedOverrides.empty() &&
			ResourcesEqualArtist(*pNoOpRetired) &&
			AllScalarTargetsEqual(*pNoOpRetired, MirroredScalar,
				ArtistValues.fMirroredScalar, 2u) &&
			AllColorTargetsEqual(*pNoOpRetired, MirroredColor,
				ArtistValues.vMirroredColor, 4u) &&
			pNoOpRetired->Material.SourceMaterial.strProfileId ==
				"g3.compiler.v3",
			"G3 Reimport Retires Compiler-Equal No-Op Deltas Without Losing Effective Values");

		EFFECT_DOCUMENT_DESC VanishedCompiler = CompilerV2;
		EFFECT_ELEMENT_DESC* pVanishedCompiler = FindTarget(VanishedCompiler);
		if (nullptr != pVanishedCompiler)
		{
			std::erase_if(pVanishedCompiler->Material.SourceMaterial.Textures,
				[&](const EFFECT_NAMED_TEXTURE_DESC& Row)
				{
					return Row.strName == NamedTexture;
				});
			std::erase_if(pVanishedCompiler->Material.SourceMaterial.Scalars,
				[&](const EFFECT_NAMED_FLOAT_DESC& Row)
				{
					return Row.strName == SourceOnlyScalar;
				});
			std::erase_if(pVanishedCompiler->Material.SourceMaterial.Vectors,
				[&](const EFFECT_NAMED_FLOAT4_DESC& Row)
				{
					return Row.strName == SourceOnlyColor;
				});
		}
		EFFECT_DOCUMENT_DESC VanishedResult;
		EFFECT_GENERIC_AUTHORED_REIMPORT_REPORT VanishedReport;
		const bool_t bVanishedReimported = nullptr != pVanishedCompiler &&
			CEffectDocumentCodec::Build_GenericAuthoredElementReimportStage(
				VanishedCompiler, Reimported, Request, VanishedResult, status,
				&VanishedReport);
		const auto HasDrop = [&](const EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_KIND Kind,
			const EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_REASON Reason,
			const std::string_view TargetId)
		{
			return std::any_of(VanishedReport.DroppedOverrides.begin(),
				VanishedReport.DroppedOverrides.end(),
				[&](const EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_DESC& Drop)
				{
					return Drop.eKind == Kind && Drop.eReason == Reason &&
						Drop.strTargetId == TargetId;
				});
		};
		EFFECT_ELEMENT_DESC* pVanishedResult = bVanishedReimported ?
			FindTarget(VanishedResult) : nullptr;
		runner.Require(nullptr != pVanishedResult &&
			VanishedReport.DroppedOverrides.size() == 3u &&
			HasDrop(EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_KIND::RESOURCE,
				EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_REASON::
					RESOURCE_SLOT_VANISHED, NamedTextureSlotId) &&
			HasDrop(EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_KIND::SCALAR,
				EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_REASON::
					SCALAR_PARAMETER_VANISHED, SourceOnlyScalar) &&
			HasDrop(EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_KIND::COLOR,
				EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_REASON::
					COLOR_PARAMETER_VANISHED, SourceOnlyColor) &&
			pVanishedResult->AuthoringOverrides.ResourceBindings.size() == 2u &&
			pVanishedResult->AuthoringOverrides.Scalars.size() == 2u &&
			pVanishedResult->AuthoringOverrides.Colors.size() == 2u,
			"G3 Reimport Drops Only Vanished Targets With Three Typed Reasons");

		const auto ReimportRejectsWithoutCommit = [&](
			const EFFECT_DOCUMENT_DESC& Compiler,
			const EFFECT_DOCUMENT_DESC& Existing,
			const EFFECT_GENERIC_AUTHORED_ELEMENT_REIMPORT_REQUEST& ProbeRequest)
		{
			EFFECT_DOCUMENT_DESC Sentinel = Reimported;
			Sentinel.strDisplayName = "G3 rollback sentinel";
			const std::string SentinelBefore =
				CEffectDocumentCodec::Serialize(Sentinel);
			const std::string CompilerBefore =
				CEffectDocumentCodec::Serialize(Compiler);
			const std::string ExistingInputBefore =
				CEffectDocumentCodec::Serialize(Existing);
			EFFECT_GENERIC_AUTHORED_REIMPORT_REPORT Report;
			Report.DroppedOverrides.push_back({
				EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_KIND::RESOURCE,
				EFFECT_GENERIC_AUTHORED_REIMPORT_DROP_REASON::
					RESOURCE_SLOT_VANISHED,
				"rollback.sentinel" });
			std::string ExpectedError;
			return !CEffectDocumentCodec::Build_GenericAuthoredElementReimportStage(
					Compiler, Existing, ProbeRequest, Sentinel, ExpectedError,
					&Report) &&
				!ExpectedError.empty() &&
				CEffectDocumentCodec::Serialize(Sentinel) == SentinelBefore &&
				CEffectDocumentCodec::Serialize(Compiler) == CompilerBefore &&
				CEffectDocumentCodec::Serialize(Existing) == ExistingInputBefore &&
				Report.DroppedOverrides.size() == 1u &&
				Report.DroppedOverrides.front().strTargetId ==
					"rollback.sentinel";
		};
		EFFECT_DOCUMENT_DESC UnsafeExisting = RoundTrip;
		EFFECT_ELEMENT_DESC* pUnsafeExisting = FindTarget(UnsafeExisting);
		if (nullptr != pUnsafeExisting)
		{
			pUnsafeExisting->AuthoringOverrides.ResourceBindings.front().
				strAssetId = "../unsafe.dds";
		}
		EFFECT_DOCUMENT_DESC TypeChangedCompiler = CompilerV2;
		EFFECT_ELEMENT_DESC* pTypeChangedCompiler =
			FindTarget(TypeChangedCompiler);
		if (nullptr != pTypeChangedCompiler)
		{
			std::erase_if(pTypeChangedCompiler->Material.SourceMaterial.Scalars,
				[&](const EFFECT_NAMED_FLOAT_DESC& Row)
				{
					return Row.strName == SourceOnlyScalar;
				});
			pTypeChangedCompiler->Material.SourceMaterial.Vectors.push_back(
				{ SourceOnlyScalar, "g3", { 1.f, 1.f, 1.f, 1.f } });
		}
		EFFECT_GENERIC_AUTHORED_ELEMENT_REIMPORT_REQUEST InvalidRequest;
		const bool_t bReimportRollback = nullptr != pUnsafeExisting &&
			nullptr != pTypeChangedCompiler &&
			ReimportRejectsWithoutCommit(CompilerV2, RoundTrip,
				InvalidRequest) &&
			ReimportRejectsWithoutCommit(CompilerV2, UnsafeExisting, Request) &&
			ReimportRejectsWithoutCommit(CompilerV2, Duplicate, Request) &&
			ReimportRejectsWithoutCommit(CompilerV2, EffectiveMismatch, Request) &&
			ReimportRejectsWithoutCommit(
				TypeChangedCompiler, RoundTrip, Request) &&
			ReimportRejectsWithoutCommit(
				MirrorScalarMismatch, RoundTrip, Request) &&
			ReimportRejectsWithoutCommit(
				MirrorColorMismatch, RoundTrip, Request);
		runner.Require(bReimportRollback,
			"G3 Invalid Reimport Preserves Output Report Compiler And Existing Documents Transactionally");
	}

	void Test_EffectCharacterMeshResourceBoundary(TEST_RUNNER& runner)
	{
		using namespace Client;
		constexpr const char_t* WeaponAssetId =
			"Character/Valtan/ValtanWeapon.wmodel";
		constexpr const char_t* CompilerModelAssetId =
			"Effect/Valtan/Meshes/FX_SM_00/fm_a_broken_007.wmodel";
		constexpr const char_t* ReimportedCompilerModelAssetId =
			"Effect/Valtan/Meshes/FX_SM_00/fm_a_cylinder_002.wmodel";
		constexpr const char_t* EffectTextureAssetId =
			"Effect/Valtan/Textures/EFMASTER_MATERIAL_PROLOGUE/diffuse.dds";
		constexpr const char_t* CharacterTextureAssetId =
			"Character/Valtan/textures/wp_mn_rpbf_01_d.dds";

		SCOPED_ENVIRONMENT_VARIABLE RuntimeResourceRoot(
			L"LOSTARK_RESOURCE_ROOT");
		std::filesystem::path RuntimeResourceRootPath;
		if (RuntimeResourceRoot.Was_Defined() &&
			!RuntimeResourceRoot.Get_OriginalValue().empty())
		{
			RuntimeResourceRootPath = RuntimeResourceRoot.Get_OriginalValue();
		}
		else
		{
			RuntimeResourceRootPath =
				CProjectDataRoot::Get().parent_path() / L"Client" / L"Bin" /
				L"Resources";
		}
		std::error_code ResourceError;
		const bool_t bHasResourceRoot = RuntimeResourceRoot.Was_Defined() &&
			!RuntimeResourceRoot.Get_OriginalValue().empty();
		const bool_t bResourceRootReady =
			std::filesystem::is_directory(RuntimeResourceRootPath, ResourceError) &&
			!ResourceError &&
			(bHasResourceRoot ||
				RuntimeResourceRoot.Set(RuntimeResourceRootPath.c_str()));
		runner.Require(bResourceRootReady,
			"Character Mesh Boundary Resolves The Physical Resources Root");
		if (!bResourceRootReady)
			return;

		EFFECT_RESOURCE_FILE_KIND eResourceKind =
			EFFECT_RESOURCE_FILE_KIND::END;
		const bool_t bNarrowAdmission =
			!CEffectDocumentCodec::Is_SafeResourceAssetId(WeaponAssetId) &&
			CEffectDocumentCodec::Is_SafeModelCueAssetId(WeaponAssetId) &&
			CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "meshModel", WeaponAssetId,
				&eResourceKind) &&
			eResourceKind == EFFECT_RESOURCE_FILE_KIND::MODEL &&
			CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::PARTICLE, "meshModel", WeaponAssetId) &&
			!CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::DECAL, "meshModel", WeaponAssetId) &&
			!CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "base", WeaponAssetId) &&
			!CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "meshModel", CharacterTextureAssetId) &&
			CEffectDocumentCodec::Is_SafeElementResourceAssetId(
				EFFECT_ELEMENT_KIND::MESH, "base", EffectTextureAssetId);
		runner.Require(bNarrowAdmission,
			"Character WModel Is Admitted Only By MeshModel On Mesh Or Particle");

		const auto MakeDocument = [=](const std::string& ModelAssetId)
		{
			EFFECT_DOCUMENT_DESC Document;
			Document.strEffectAssetId =
				"effect.valtan.high-jump.axe-resource-boundary.fixture";
			Document.strDisplayName = "Valtan axe resource boundary fixture";
			EFFECT_ELEMENT_DESC Element;
			Element.strElementId = "fixture-axe-mesh";
			Element.strDisplayName = "Fixture axe mesh";
			Element.strGroupId = "manual.valtan.axe";
			Element.eKind = EFFECT_ELEMENT_KIND::MESH;
			Element.ResourceBindings.push_back({ "meshModel", ModelAssetId });
			Element.ResourceBindings.push_back(
				{ "base", EffectTextureAssetId });
			Element.Detail.Mesh.bUseModelMaterial = true;
			Element.Detail.Mesh.fModelPreScale = 1.f;
			Document.Elements.push_back(std::move(Element));
			return Document;
		};
		std::string Status;
		EFFECT_DOCUMENT_DESC CharacterDocument = MakeDocument(WeaponAssetId);
		std::vector<std::string> Dependencies;
		CEffectDocumentCodec::Collect_ResourceAssetIds(
			CharacterDocument, Dependencies);
		const bool_t bDocumentRoundTrip =
			CEffectDocumentCodec::Validate(CharacterDocument, Status) &&
			Dependencies.size() == 2u &&
			std::find(Dependencies.begin(), Dependencies.end(), WeaponAssetId) !=
				Dependencies.end();
		EFFECT_DOCUMENT_DESC ParsedDocument;
		const std::string CharacterJson =
			CEffectDocumentCodec::Serialize(CharacterDocument);
		const bool_t bParsed = bDocumentRoundTrip &&
			CEffectDocumentCodec::Parse(CharacterJson, ParsedDocument, Status) &&
			CEffectDocumentCodec::Serialize(ParsedDocument) == CharacterJson;
		runner.Require(bParsed,
			"Character MeshModel Validates Collects And Round-Trips Canonically");
		if (!bParsed)
		{
			std::cout << "[DETAIL] Character mesh boundary: " << Status << '\n';
			return;
		}

		EFFECT_DOCUMENT_DESC Authored = MakeDocument(CompilerModelAssetId);
		EFFECT_ELEMENT_DESC& AuthoredElement = Authored.Elements.front();
		const bool_t bOverrideAndReset =
			CEffectDocumentCodec::Set_AuthoringResourceOverride(
				AuthoredElement, "meshModel", WeaponAssetId, Status) &&
			AuthoredElement.ResourceBindings.front().strAssetId == WeaponAssetId &&
			AuthoredElement.AuthoringOverrides.ResourceBindings.size() == 1u &&
			AuthoredElement.AuthoringOverrides.ResourceBindings.front().
				strCompilerAssetId == CompilerModelAssetId &&
			CEffectDocumentCodec::Validate(Authored, Status) &&
			CEffectDocumentCodec::Reset_AuthoringResourceOverride(
				AuthoredElement, "meshModel", Status) &&
			AuthoredElement.ResourceBindings.front().strAssetId ==
				CompilerModelAssetId &&
			AuthoredElement.AuthoringOverrides.ResourceBindings.empty() &&
			CEffectDocumentCodec::Validate(Authored, Status);
		runner.Require(bOverrideAndReset,
			"Character MeshModel Override Persists Its Compiler Baseline And Resets");

		const auto ConfigurePortableMeshParticle = [](
			EFFECT_ELEMENT_DESC& Element)
		{
			const auto Distribution = [](const std::string& PropertyPath,
				const float4_t& Minimum, const float4_t& Maximum)
			{
				EFFECT_DISTRIBUTION_DESC Result;
				Result.strPropertyPath = PropertyPath;
				Result.iComponentCount = 1u;
				Result.iOperation = 1u;
				Result.vDefaultMinimum = Minimum;
				Result.vDefaultMaximum = Maximum;
				return Result;
			};
			Element.eKind = EFFECT_ELEMENT_KIND::PARTICLE;
			Element.SourceRecipe.bEnabled = true;
			Element.SourceRecipe.strRendererShape = "mesh";
			Element.SourceRecipe.fEmitterDurationSeconds = 1.f;
			Element.SourceRecipe.iEmitterLoopCount = 1u;
			Element.SourceRecipe.Bursts.push_back({ 0.f, 1u, 1u });
			EFFECT_SOURCE_MODULE_DESC Required;
			Required.strStableId = "fixture.required";
			Required.strClassName = "particlemodulerequired";
			Required.strObjectPath = "Harness.Fixture.Required";
			Required.Distributions.push_back(Distribution(
				"spawnrate", float4_t{}, float4_t{}));
			Element.SourceRecipe.Modules.push_back(std::move(Required));
			EFFECT_SOURCE_MODULE_DESC Spawn;
			Spawn.strStableId = "fixture.spawn";
			Spawn.strClassName = "particlemodulespawn";
			Spawn.strObjectPath = "Harness.Fixture.Spawn";
			Spawn.Distributions.push_back(Distribution(
				"rate", float4_t{}, float4_t{}));
			Spawn.Distributions.push_back(Distribution(
				"ratescale", { 1.f, 0.f, 0.f, 0.f },
				{ 1.f, 0.f, 0.f, 0.f }));
			Element.SourceRecipe.Modules.push_back(std::move(Spawn));
			EFFECT_SOURCE_MODULE_DESC Lifetime;
			Lifetime.strStableId = "fixture.lifetime";
			Lifetime.strClassName = "particlemodulelifetime";
			Lifetime.strObjectPath = "Harness.Fixture.Lifetime";
			Lifetime.Distributions.push_back(Distribution(
				"lifetime", { 1.f, 0.f, 0.f, 0.f },
				{ 1.f, 0.f, 0.f, 0.f }));
			Element.SourceRecipe.Modules.push_back(std::move(Lifetime));
			EFFECT_SOURCE_MODULE_DESC TypeData;
			TypeData.strStableId = "fixture.typedata";
			TypeData.strClassName = "particlemoduletypedatamesh";
			TypeData.strObjectPath = "Harness.Fixture.TypeDataMesh";
			Element.SourceRecipe.Modules.push_back(std::move(TypeData));
		};
		EFFECT_DOCUMENT_DESC ReimportExisting =
			MakeDocument(CompilerModelAssetId);
		ConfigurePortableMeshParticle(ReimportExisting.Elements.front());
		const bool_t bExistingOverride =
			CEffectDocumentCodec::Set_AuthoringResourceOverride(
				ReimportExisting.Elements.front(), "meshModel", WeaponAssetId,
				Status);
		EFFECT_DOCUMENT_DESC ReimportCompiler =
			MakeDocument(ReimportedCompilerModelAssetId);
		ConfigurePortableMeshParticle(ReimportCompiler.Elements.front());
		const std::string ExistingBefore =
			CEffectDocumentCodec::Serialize(ReimportExisting);
		const std::string CompilerBefore =
			CEffectDocumentCodec::Serialize(ReimportCompiler);
		EFFECT_GENERIC_AUTHORED_ELEMENT_REIMPORT_REQUEST ReimportRequest;
		ReimportRequest.strElementId = "fixture-axe-mesh";
		EFFECT_DOCUMENT_DESC Reimported = CharacterDocument;
		EFFECT_GENERIC_AUTHORED_REIMPORT_REPORT ReimportReport;
		const bool_t bReimported = bExistingOverride &&
			CEffectDocumentCodec::Build_GenericAuthoredElementReimportStage(
				ReimportCompiler, ReimportExisting, ReimportRequest, Reimported,
				Status, &ReimportReport);
		const EFFECT_ELEMENT_DESC* pReimportedElement =
			bReimported && Reimported.Elements.size() == 1u ?
				&Reimported.Elements.front() : nullptr;
		const bool_t bReimportPreserved = nullptr != pReimportedElement &&
			pReimportedElement->ResourceBindings.front().strAssetId ==
				WeaponAssetId &&
			pReimportedElement->AuthoringOverrides.ResourceBindings.size() == 1u &&
			pReimportedElement->AuthoringOverrides.ResourceBindings.front().
				strCompilerAssetId == ReimportedCompilerModelAssetId &&
			ReimportReport.DroppedOverrides.empty() &&
			CEffectDocumentCodec::Serialize(ReimportExisting) == ExistingBefore &&
			CEffectDocumentCodec::Serialize(ReimportCompiler) == CompilerBefore &&
			CEffectDocumentCodec::Validate(Reimported, Status);
		runner.Require(bReimportPreserved,
			"Character MeshModel Reimport Preserves Artist Asset And Rebases Compiler Baseline");
		if (!bReimportPreserved)
			std::cout << "[DETAIL] Character mesh reimport: " << Status << '\n';

		const auto RejectsOverrideWithoutMutation = [&](
			const std::string_view SlotId, const std::string& AssetId)
		{
			EFFECT_DOCUMENT_DESC Probe = MakeDocument(CompilerModelAssetId);
			const std::string Before = CEffectDocumentCodec::Serialize(Probe);
			std::string ExpectedError;
			return !CEffectDocumentCodec::Set_AuthoringResourceOverride(
					Probe.Elements.front(), SlotId, AssetId, ExpectedError) &&
				!ExpectedError.empty() &&
				CEffectDocumentCodec::Serialize(Probe) == Before;
		};
		const bool_t bUnsafeOverridesRollback =
			RejectsOverrideWithoutMutation("base", WeaponAssetId) &&
			RejectsOverrideWithoutMutation("meshModel", CharacterTextureAssetId) &&
			RejectsOverrideWithoutMutation("meshModel",
				"Character/Valtan/../ValtanWeapon.wmodel") &&
			RejectsOverrideWithoutMutation("meshModel",
				"Character\\Valtan\\ValtanWeapon.wmodel") &&
			RejectsOverrideWithoutMutation("meshModel",
				"C:/Character/Valtan/ValtanWeapon.wmodel") &&
			RejectsOverrideWithoutMutation("meshModel",
				"Character/Valtan/MissingWeapon.wmodel");
		runner.Require(bUnsafeOverridesRollback,
			"Character Mesh Override Rejects Wrong Role Extension Traversal Drive Backslash And Missing Assets Transactionally");

		EFFECT_DOCUMENT_DESC InvalidDocument = CharacterDocument;
		InvalidDocument.Elements.front().ResourceBindings.front().strAssetId =
			"Character/Valtan/../ValtanWeapon.wmodel";
		EFFECT_DOCUMENT_DESC ParseSentinel = CharacterDocument;
		ParseSentinel.strDisplayName = "parse rollback sentinel";
		const std::string SentinelBefore =
			CEffectDocumentCodec::Serialize(ParseSentinel);
		std::string ExpectedError;
		const bool_t bParseRollback =
			!CEffectDocumentCodec::Parse(
				CEffectDocumentCodec::Serialize(InvalidDocument),
				ParseSentinel, ExpectedError) &&
			!ExpectedError.empty() &&
			CEffectDocumentCodec::Serialize(ParseSentinel) == SentinelBefore;
		runner.Require(bParseRollback,
			"Invalid Character Mesh Document Parse Preserves The Prior Product");
	}

	void Test_ActionPresentationTimeline(TEST_RUNNER& runner)
	{
		using namespace Client;
		std::vector<ACTION_PRESENTATION_CLIP_TIMING> clips =
		{
			{ 2.f, 500u, 0.5f, false },
			{ 1.f, 0u, 2.f, false }
		};
		f32_t sourceDuration = 0.f;
		f32_t wallDuration = 0.f;
		runner.Require(
			CActionPresentationTimeline::Resolve_ClipDuration(
				clips[0], sourceDuration, wallDuration) &&
			std::abs(sourceDuration - 0.5f) < 0.000001f &&
			std::abs(wallDuration - 1.f) < 0.000001f,
			"Action Timeline Applies PlayMs Before PlayRate");

		ACTION_PRESENTATION_SAMPLE sample;
		const std::vector<ACTION_PRESENTATION_CLIP_TIMING> sourceSegment =
		{
			{ 3.f, 1000u, 2.f, false, 0.75f }
		};
		f32_t sourceSegmentCueWallOffset = -1.f;
		runner.Require(
			CActionPresentationTimeline::Resolve_ClipDuration(
				sourceSegment.front(), sourceDuration, wallDuration) &&
			std::abs(sourceDuration - 1.f) < 0.000001f &&
			std::abs(wallDuration - 0.5f) < 0.000001f &&
			CActionPresentationTimeline::Resolve_Sample(
				sourceSegment, 0.125f, sample) &&
			std::abs(sample.fClipSourceTimeSeconds - 1.f) < 0.000001f &&
			CActionPresentationTimeline::Resolve_CueWallOffset(
				sourceSegment, 0u, 1.25f, 0u,
				sourceSegmentCueWallOffset) &&
			std::abs(sourceSegmentCueWallOffset - 0.25f) < 0.000001f &&
			!CActionPresentationTimeline::Resolve_CueWallOffset(
				sourceSegment, 0u, 0.5f, 0u,
				sourceSegmentCueWallOffset),
			"Action Timeline Applies Source Start Play Rate Sample And Cue Wall Offset On One Clock");

		ACTION_PRESENTATION_CUE_PREVIEW_TIMING bossCuePreview;
		bossCuePreview.fClipSourceStartSeconds = 0.4f;
		bossCuePreview.fPlayRate = 2.f;
		bossCuePreview.fCueSourceStartSeconds = 1.f;
		bossCuePreview.fCueSourceEndSeconds = 1.4f;
		bossCuePreview.bHasCueSourceEnd = true;
		ACTION_PRESENTATION_CUE_PREVIEW_SAMPLE bossCueSample;
		const bool_t hiddenBeforeCue =
			CActionPresentationTimeline::Resolve_CuePreviewSample(
				bossCuePreview, 0.299f, bossCueSample) &&
			!bossCueSample.bVisible &&
			std::abs(bossCueSample.fCueWallStartSeconds - 0.3f) < 0.000001f;
		const bool_t startsAtZero =
			CActionPresentationTimeline::Resolve_CuePreviewSample(
				bossCuePreview, 0.3f, bossCueSample) &&
			bossCueSample.bVisible &&
			std::abs(bossCueSample.fEffectSampleSeconds) < 0.000001f;
		const bool_t samplesAtClipRate =
			CActionPresentationTimeline::Resolve_CuePreviewSample(
				bossCuePreview, 0.4f, bossCueSample) &&
			bossCueSample.bVisible &&
			std::abs(bossCueSample.fEffectSampleSeconds - 0.2f) < 0.000001f;
		const bool_t hiddenAtExactCueEnd =
			CActionPresentationTimeline::Resolve_CuePreviewSample(
				bossCuePreview, 0.5f, bossCueSample) &&
			!bossCueSample.bVisible &&
			std::abs(bossCueSample.fCueWallEndSeconds - 0.5f) < 0.000001f;
		runner.Require(hiddenBeforeCue && startsAtZero &&
			samplesAtClipRate && hiddenAtExactCueEnd &&
			!CActionPresentationTimeline::Resolve_CuePreviewSample(
				ACTION_PRESENTATION_CUE_PREVIEW_TIMING{
					0.4f, 2.f, 1.f, 1.f, true }, 0.3f, bossCueSample),
			"Valtan Product Preview Maps Source Cue Windows Through Clip Play Rate");
		runner.Require(
			CActionPresentationTimeline::
				Should_ReleaseCompletedAnimationClock(
					true, false, true, true, 3.f, 3.f) &&
			!CActionPresentationTimeline::
				Should_ReleaseCompletedAnimationClock(
					true, true, true, true, 3.f, 3.f) &&
			!CActionPresentationTimeline::
				Should_ReleaseCompletedAnimationClock(
					true, false, false, true, 3.f, 3.f) &&
			!CActionPresentationTimeline::
				Should_ReleaseCompletedAnimationClock(
					true, false, true, false, 3.f, 3.f) &&
			!CActionPresentationTimeline::
				Should_ReleaseCompletedAnimationClock(
					true, false, true, true, 2.9f, 3.f),
			"Valtan Product Preview Releases Completed Non Loop Animation Clock For Natural Effect Tail");

		runner.Require(
			CActionPresentationTimeline::Resolve_Sample(clips, 1.f, sample) &&
			1u == sample.iClipIndex &&
			std::abs(sample.fClipSourceTimeSeconds) < 0.000001f,
			"Action Timeline Exact Boundary Selects Next Sequential Clip");
		runner.Require(
			CActionPresentationTimeline::Resolve_Sample(clips, 1.125f, sample) &&
			1u == sample.iClipIndex &&
			std::abs(sample.fClipSourceTimeSeconds - 0.25f) < 0.000001f,
			"Action Timeline Converts Wall Overshoot By Current Clip Rate");

		const std::vector<ACTION_PRESENTATION_CLIP_TIMING> hold =
			{ { 1.f, 400u, 2.f, true } };
		runner.Require(
			CActionPresentationTimeline::Resolve_Sample(hold, 0.65f, sample) &&
			0u == sample.iClipIndex && 3u == sample.iLoopEpoch &&
			std::abs(sample.fClipSourceTimeSeconds - 0.1f) < 0.00001f,
			"Action Timeline HOLD Resolves Loop Epoch And Source Phase");
		f32_t cueWallOffset = 0.f;
		runner.Require(
			CActionPresentationTimeline::Resolve_CueWallOffset(
				hold, 0u, 0.1f, 2u, cueWallOffset) &&
			std::abs(cueWallOffset - 0.45f) < 0.00001f,
			"Action Timeline Cue Identity Includes HOLD Loop Epoch");

		f32_t actionAge = 0.f;
		runner.Require(
			CActionPresentationTimeline::Is_ForwardTick(1u, UINT32_MAX) &&
			!CActionPresentationTimeline::Is_ForwardTick(UINT32_MAX, 1u) &&
			!CActionPresentationTimeline::Is_ForwardTick(1u, 1u) &&
			CActionPresentationTimeline::Try_ResolveActionAgeSeconds(
				1u, UINT32_MAX, 30.f, actionAge) &&
			std::abs(actionAge - 1.f / 30.f) < 0.000001f,
			"Action Timeline Skips Reserved Zero Tick Across Wrap");
		runner.Require(
			CActionPresentationTimeline::Try_ResolveActionAgeSeconds(
				1u, UINT32_MAX - 1u, 30.f, actionAge) &&
			std::abs(actionAge - 2.f / 30.f) < 0.000001f,
			"Action Timeline Counts Two Forward Ticks Across Reserved Zero");

		ANIMATION_SKILL_BINDING_DOCUMENT dimensionMaster;
		std::string status;
		const std::filesystem::path bindingPath =
			CAnimationSkillBindingDocument::Resolve_Path("DimensionMaster");
		const bool_t bindingParsed =
			CAnimationSkillBindingDocument::Parse_Text(
				Read_Text(bindingPath), dimensionMaster, status);
		const auto binding = std::find_if(
			dimensionMaster.Bindings.begin(), dimensionMaster.Bindings.end(),
			[](const ANIMATION_SKILL_BINDING& candidate)
			{
				return 2050240u == candidate.iSkillId;
			});
		const std::filesystem::path cuePath = CProjectDataRoot::Resolve(
			"Animation/Authored/DimensionMaster/DimensionMaster.animevents");
		const std::string cueText = Read_Text(cuePath);
		const bool_t exactPriorClipProductCue = std::string::npos != cueText.find(
			"\"pc_sp_m_00_sk_sk_telekinesisthrust_01\" EFFECT startms=0 "
			"payload=\"effect.dimensionmaster.skill.2050240.authored-baseline.clip1\" "
			"effectref=asset");
		bool_t exactBinding = bindingParsed &&
			binding != dimensionMaster.Bindings.end() &&
			1u == binding->Stages.size() &&
			2u == binding->Stages[0].Clips.size();
		if (exactBinding)
		{
			exactBinding =
				binding->Stages[0].Clips[0].strClipName ==
					"pc_sp_m_00_sk_sk_telekinesisthrust_01" &&
				binding->Stages[0].Clips[1].strClipName ==
					"pc_sp_m_00_sk_sk_telekinesisthrust_04";
		}
		const std::vector<ACTION_PRESENTATION_CLIP_TIMING> dm2050240 =
		{
			{ 0.25f, exactBinding ?
				binding->Stages[0].Clips[0].iPlayMs : 0u,
				exactBinding ? binding->Stages[0].Clips[0].fPlayRate : 1.f,
				false },
			{ 1.f, exactBinding ?
				binding->Stages[0].Clips[1].iPlayMs : 0u,
				exactBinding ? binding->Stages[0].Clips[1].fPlayRate : 1.f,
				false }
		};
		f32_t dmCueWallOffset = -1.f;
		const bool_t delayedPriorClipCue =
			CActionPresentationTimeline::Resolve_Sample(
				dm2050240, 0.5f, sample) &&
			1u == sample.iClipIndex &&
			CActionPresentationTimeline::Resolve_CueWallOffset(
				dm2050240, 0u, 0.f, 0u, dmCueWallOffset) &&
			std::abs(dmCueWallOffset) < 0.000001f &&
			std::abs((0.5f - dmCueWallOffset) *
				dm2050240[0].fPlayRate - 0.5f) < 0.000001f;
		runner.Require(exactBinding && exactPriorClipProductCue &&
			delayedPriorClipCue,
			"DimensionMaster 2050240 Delayed First Snapshot Retains Prior Clip Product Cue");
	}

	std::string Make_ValtanCameraFixture(
		const uint32_t formatVersion = 3u,
		const bool_t includeUnknownRootKey = false,
		const bool_t duplicateTuple = false)
	{
		std::ostringstream text;
		text << "{\"schema\":\"lostark.encounter-cinematic-camera\",";
		text << "\"formatVersion\":" << formatVersion << ',';
		text << "\"encounterId\":\"ENCOUNTER_VALTAN\",";
		text << "\"provenance\":\"PROJECT_AUTHORED\",";
		if (includeUnknownRootKey)
			text << "\"unknown\":true,";
		text << "\"cues\":[";
		const auto appendCue = [&text](const char_t* cueId)
		{
			text << "{\"cueId\":\"" << cueId << "\",";
			text << "\"patternId\":\"VALTAN_ARENA_BREAK_109\",";
			/* WIDE_REVEAL is the one authored stage long enough to hold this
			2000ms fixture, so the tick arithmetic below stays exact. */
			text << "\"stageId\":\"WIDE_REVEAL\",\"durationMs\":2000,";
			text << "\"easing\":\"LINEAR\",";
			text << "\"shakeAmplitude\":0,\"shakeDurationMs\":0,";
			text << "\"keyframes\":[";
			text << "{\"timeMs\":0,\"eye\":[0,2,-4],\"lookAt\":[0,0,0],\"fovYDegrees\":60},";
			text << "{\"timeMs\":1000,\"eye\":[10,2,-4],\"lookAt\":[0,0,0],\"fovYDegrees\":40},";
			text << "{\"timeMs\":2000,\"eye\":[20,2,-4],\"lookAt\":[0,0,0],\"fovYDegrees\":30}]}";
		};
		appendCue("fixture.valtan.109");
		if (duplicateTuple)
		{
			text << ',';
			appendCue("fixture.valtan.109.duplicate");
		}
		/* The sky layer shares this document so both presentations read one
		   authoritative time axis. An empty array is a valid authored state. */
		text << "],\"skyCues\":[],\"deathCue\":{}}";
		return text.str();
	}

	std::string Make_ValtanSkyFixture(
		const std::string_view redCloudAssetId,
		const std::string_view blackApertureAssetId)
	{
		std::string text = Make_ValtanCameraFixture();
		const std::string emptyArray = "\"skyCues\":[]";
		const size_t offset = text.find(emptyArray);
		if (std::string::npos == offset)
			return {};
		std::ostringstream sky;
		sky << "\"skyCues\":[{";
		sky << "\"cueId\":\"fixture.sky.valtan.109\",";
		sky << "\"patternId\":\"VALTAN_ARENA_BREAK_109\",";
		sky << "\"stageId\":\"WIDE_REVEAL\",";
		sky << "\"stageLocalStartMs\":0,\"stageLocalEndMs\":2000,";
		sky << "\"redCloudAssetId\":\"" << redCloudAssetId << "\",";
		sky << "\"blackApertureAssetId\":\"" <<
			blackApertureAssetId << "\",";
		sky << "\"cloudOpacityStart\":0.2,\"cloudOpacityEnd\":1,";
		sky << "\"apertureScaleStart\":0.4,\"apertureScaleEnd\":1,";
		sky << "\"cloudRotationDegreesPerSecond\":12}]";
		text.replace(offset, emptyArray.size(), sky.str());
		return text;
	}

